async function measureDirectoryBytes(path: string): Promise<number> {
  if (!existsSync(path)) return 0
  const stat = await lstat(path)
  if (stat.isSymbolicLink()) return 0
  if (!stat.isDirectory()) return stat.size
  let total = 0
  for (const entry of await readdir(path)) total += await measureDirectoryBytes(join(path, entry))
  return total
}

src\\adapters\\files.ts::removeEmptyDire.source_code:
function removeEmptyDirectoryTree(path: string): boolean {
  if (!existsSync(path)) return true
  const stat = lstatSync(path)
  if (!stat.isDirectory() || stat.isSymbolicLink()) return false
  for (const entry of readdirSync(path)) {
    const child = join(path, entry)
    // 目录链接（junction / 符号链接）不承载用户字节：只删链接本身，绝不跟随
    // 目标，链接指向的内容原样保留。
    if (lstatSync(child).isSymbolicLink()) {
      unlinkSync(child)
      continue
    }
    if (!removeEmptyDirectoryTree(child)) return false
  }
  rmdirSync(path)
  return true
}

src\\adapters\\files.ts::inspectDirector.source_code:
async function inspectDirectoryIdentity(path: string): Promise<DirectoryIdentity | null> {
  if (!existsSync(path)) return null
  const stat = await lstat(path, { bigint: true })
  if (!stat.isDirectory() || stat.isSymbolicLink()) return null
  return {
    device: stat.dev.toString(),
    inode: stat.ino.toString(),
    birthtimeNs: stat.birthtimeNs.toString(),
  }
}

