function createNodeFilesPort(): SessionCheckoutFilesPort {
  return {
    exists: existsSync,
    canonicalize: async (path) => realpath(resolve(path)),
    inspectDirectoryIdentity,
    ensureDirectory: (path) => mkdirSync(path, { recursive: true }),
    removeEmptyDirectoryTree,
    quarantineDirectoryTree,
    removeDirectoryTree,
    measureDirectoryBytes,
    readTextFile: (path) => (existsSync(path) ? readFileSync(path, 'utf8') : null),
    copyFile: (from, to) => {
      mkdirSync(dirname(to), { recursive: true })
      if (existsSync(to)) rmSync(to, { force: true })
      copyFileSync(from, to)
    },
    isSymbolicLink: async (path) => {
      try { return lstatSync(path).isSymbolicLink() } catch { return false }
    },
  }
}

