  open: boolean
  onClose: () => void
  adapter: WorktreeConsoleAdapter
  sessionId: string
  t: ClientTranslator
  currentBranch: string | null
  /** Open the tag manager pointing at this commit. */
  onTagCommit?: (oid: string) => void
  /** Open the tag manager without a target (HEAD). */
