function normalizePath(path: string): string {
  const resolved = path.replace(/\\/gu, '/')
  const withSlash = resolved.endsWith('/') ? resolved : `${resolved}/`
  return process.platform === 'win32' ? withSlash.toLowerCase() : withSlash
}

