function domainError(
  code: SessionCheckoutErrorCode,
  message: string,
  continuation?: WorktreeConsoleError['continuation'],
): Error {
  return Object.assign(new Error(message), { code, ...(continuation === undefined ? {} : { continuation }) })
}

