function consoleFailure(error: unknown): WorktreeConsoleOutcome<never> {
  if (
    error instanceof Error
    && 'code' in error
    && typeof error.code === 'string'
    && (SESSION_CHECKOUT_ERROR_CODES as readonly string[]).includes(error.code)
  ) {
    const continuation = 'continuation' in error ? error.continuation : undefined
    return {
      ok: false,
      error: {
        code: error.code as SessionCheckoutErrorCode,
        message: error.message,
        ...(continuation === undefined ? {} : { continuation: continuation as WorktreeConsoleError['continuation'] }),
      },
    }
  }
  // Verbatim third-party messages are intentional for the local console UI
  // (kept observable by tests/host-i18n.test.ts); sanitize here before any
  // future remote transport serializes WorktreeConsoleError off-machine.
  // ponytail: local-only leak ceiling; truncate/replace if a remote face lands.
  return {
    ok: false,
    error: {
      code: 'git_error',
      message: error instanceof Error ? error.message : hostMessage('worktreeConsoleOperationFailed'),
    },
  }
}

