function failure<T>(
  code: WorktreeConsoleError['code'],
  message: string,
  details?: WorktreeConsoleError['details'],
  continuation?: WorktreeConsoleError['continuation'],
): WorktreeConsoleOutcome<T> {
  return {
    ok: false,
    error: {
      code,
      message,
      ...(details === undefined ? {} : { details }),
      ...(continuation === undefined ? {} : { continuation }),
    },
  }
}

