function projectRecord(
  record: ManagedCheckoutRecord,
  callerSessionId: string,
  observed?: {
    snapshot?: Pick<GitCheckoutSnapshot, 'branch' | 'headOid'>
    dirty?: boolean
    summary?: ManagedWorktreeSummaryView
    ownerSessionAvailable?: boolean
    linkedRead?: boolean
    deliveryProof?: WorktreeConsoleDeliveryProof
  },
): WorktreeConsoleTargetSummary {
  const projectedReview = review(record)
  const projectedProof = observed?.linkedRead === true
    ? undefined
    : deliveryProof(record, observed?.deliveryProof)
  const delivery = record.delivery
  return {
    project: { id: record.projectId, name: record.projectName },
    checkoutId: record.checkoutId,
    sourceSessionId: record.sourceSessionId ?? record.ownerSessionId,
    ownerSessionId: record.ownerSessionId,
    targetSessionId: record.ownerSessionId,
    iteration: iteration(record),
    revision: record.revision,
    state: consoleStateFromDomain({ kind: 'isolated', phase: record.phase, deliveryState: delivery.state }),
    phase: record.phase,
    dirty: observed?.dirty ?? observed?.summary?.dirty ?? false,
    currentOid: observed?.snapshot?.headOid ?? fallbackOid(record),
    commitOid: commitOid(record),
    // The Session's own branch wins over the fork point: `sourceRef` names where
    // the Worktree branched from, which for a legacy record can be another
    // Session's branch — labelling the sidebar card with that would repeat the
    // very attribution mistake the session branch was introduced to end.
    sourceBranch: sourceBranchFromRef(record.sessionBranch ?? record.sourceRef),
    ...(delivery.state === 'retained' ? {
      retention: delivery.retention,
      retainedAt: delivery.retainedAt,
      expiresAt: delivery.expiresAt,
    } : {}),
    ...((delivery.state === 'retained' || delivery.state === 'finalized') && delivery.cleanupMessage !== undefined
      ? { cleanupMessage: hostPersistedCleanupMessage(delivery.cleanupMessage, hostMessage, delivery.cleanupMessageKey) }
      : {}),
    ...((delivery.state === 'retained' || delivery.state === 'finalized') && delivery.cleanupReason !== undefined
      ? { cleanupReason: delivery.cleanupReason }
      : {}),
    ...(record.permanent === true ? { permanent: true } : {}),
    ...(projectedProof === undefined ? {} : { deliveryProof: projectedProof }),
    ...(projectedReview === undefined ? {} : { review: projectedReview }),
    ...((record.checkpoints?.length ?? 0) > 0 ? {
      checkpoints: record.checkpoints!.map(checkpoint => ({
        checkpointId: checkpoint.checkpointId,
        sequence: checkpoint.sequence,
        reviewId: checkpoint.reviewId,
        createdAt: checkpoint.createdAt,
        summary: checkpoint.summary,
        validationStatus: checkpoint.validationStatus,
        changedFiles: [...checkpoint.changedFiles],
      })),
    } : {}),
    ...(checkpointGenerationForRecord(record) ? { checkpointGeneration: checkpointGenerationForRecord(record) } : {}),
    ...(delivery.state === 'ready_for_review' ? { reviewSlot: 'available' as const } : {}),
    ...(delivery.state === 'preview_detached' ? {
      previewRecovery: {
        previewId: delivery.preview.previewId,
        detachedAt: delivery.detachedAt,
        reason: delivery.reason,
        attemptedAction: delivery.attemptedAction,
      },
    } : {}),
    capabilities: capabilities(
      record,
      callerSessionId,
      observed?.ownerSessionAvailable,
      observed?.linkedRead,
    ),
  }
}

function projectDetails(
  record: ManagedCheckoutRecord,
  callerSessionId: string,
  managedRoot: string | null,
  snapshot?: Pick<GitCheckoutSnapshot, 'branch' | 'headOid'>,
  dirty?: boolean,
  ownerSessionAvailable?: boolean,
  linkedRead = false,
  observedDeliveryProof?: WorktreeConsoleDeliveryProof,
  settledLocalBranch?: string | null,
): WorktreeConsoleTargetDetails {
  return {
    ...projectRecord(record, callerSessionId, {
      snapshot,
      dirty,
      ownerSessionAvailable,
      linkedRead,
      deliveryProof: observedDeliveryProof,
    }),
    managedRoot,
    sourceRoot: record.localRoot,
    sourceOid: record.baseOid,
    // The watched branch is what Git reports right now; the recorded session
    // branch is the fallback so the conversation chip keeps naming the Session's
    // own branch when the Worktree cannot be observed this instant (a frozen or
    // vanished runtime, a transient inspect failure) instead of collapsing to
    // the bare "Worktree · state" label.
    //
    // A delivered Worktree is the exception: the Session is back at the Local
    // boundary, so the chip must name the branch the user is actually standing
    // on (master, after the merge) rather than the frozen task branch. The host
    // resolves that branch with the settled record and passes it in; `undefined`
    // keeps the worktree branch, `null` means Local is not observable right now
    // and the recorded label is still the best answer.
    currentBranch: settledLocalBranch ?? snapshot?.branch ?? sourceBranchFromRef(record.sessionBranch ?? ''),
    ...(callerSessionId === record.ownerSessionId && !linkedRead && record.recoveryContinuation
      ? {
          recoveryContinuation: record.recoveryContinuation.kind === 'worktree_apply_conflict'
            ? {
                kind: record.recoveryContinuation.kind,
                requestId: record.recoveryContinuation.requestId,
                checkoutId: record.checkoutId,
                reviewId: record.recoveryContinuation.reviewId,
                revision: record.recoveryContinuation.workingRevision,
                localHeadOid: record.recoveryContinuation.localHeadOid,
                conflictingFiles: [...record.recoveryContinuation.conflictingFiles],
              }
            : record.recoveryContinuation.kind === 'worktree_review_regeneration'
              ? {
                  kind: record.recoveryContinuation.kind,
                  requestId: record.recoveryContinuation.requestId,
                  checkoutId: record.checkoutId,
                  reviewId: record.recoveryContinuation.reviewId,
                  revision: record.recoveryContinuation.revision,
                }
              : record.recoveryContinuation.kind === 'worktree_preview_recovery_analysis'
                ? {
                    kind: record.recoveryContinuation.kind,
                    requestId: record.recoveryContinuation.requestId,
                    checkoutId: record.checkoutId,
                    reviewId: record.recoveryContinuation.reviewId,
                    previewId: record.recoveryContinuation.previewId,
                    revision: record.recoveryContinuation.revision,
                    generation: record.recoveryContinuation.generation,
                  }
                : {
                    kind: record.recoveryContinuation.kind,
                    requestId: record.recoveryContinuation.requestId,
                    checkoutId: record.checkoutId,
                    sourceCheckoutId: record.recoveryContinuation.sourceCheckoutId,
                    reviewId: record.recoveryContinuation.reviewId,
                    previewId: record.recoveryContinuation.previewId,
                    revision: record.recoveryContinuation.sourceRevision,
                    generation: record.recoveryContinuation.generation,
                  },
        }
      : {}),
  }
}

