function parseNameStatus(output: Buffer): ChangedEntry[] {
  const fields = output.toString('utf8').split('\0')
  const entries: ChangedEntry[] = []
  let index = 0
  while (index < fields.length) {
    const code = fields[index++]
    if (!code) break
    // ponytail: name-status reports both R and C here; the console contract has
    // no 'copied' status, so copy semantics fold into 'renamed' (no consumer
    // distinguishes them).
    if (code.startsWith('R') || code.startsWith('C')) {
      const previousPath = fields[index++] ?? ''
      const path = fields[index++] ?? ''
      entries.push({ path, previousPath, status: 'renamed' })
      continue
    }
    const path = fields[index++] ?? ''
    entries.push({
      path,
      status: code.startsWith('A') ? 'added' : code.startsWith('D') ? 'deleted' : 'modified',
    })
  }
  return entries
}

