function createGitWorktreeReviewDiffReader(projectSkills?: ProjectSkillStore): WorktreeReviewDiffReader {
  return {
    async read(input) {
      const expected = sortedUnique(input.changedFiles)
      if (expected.some(path => !projectPath(path))) throw new Error(hostMessage('reviewChangedFilesContainsAnUnsafeProjectRelativePath'))
      const tempRoot = await mkdtemp(join(tmpdir(), 'dsh-worktree-console-diff-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      try {
        const objects = (await git(
          input.managedRoot,
          ['rev-parse', '--path-format=absolute', '--git-path', 'objects'],
          process.env,
          32 * 1024,
        )).stdout.toString('utf8').trim()
        const env: NodeJS.ProcessEnv = {
          ...process.env,
          GIT_INDEX_FILE: join(tempRoot, 'index'),
          GIT_OBJECT_DIRECTORY: objectDirectory,
          GIT_ALTERNATE_OBJECT_DIRECTORIES: objects,
          GIT_CONFIG_NOSYSTEM: '1',
        }
        await git(input.managedRoot, ['read-tree', input.baseOid], env, 16 * 1024)
        await git(input.managedRoot, ['add', '-A', '--', '.'], env, 16 * 1024)
        if (await projectSkills?.paths(input.managedRoot)) {
          const index = await git(input.managedRoot, ['ls-files', '--stage', '-z'], process.env, 4 * 1024 * 1024)
          const head = await git(input.managedRoot, ['ls-tree', '-r', '--name-only', '-z', 'HEAD'], process.env, 4 * 1024 * 1024)
          if (index.truncated || head.truncated) throw new Error('Skill tracking inventory exceeds the safe read budget')
          const carried = await projectSkills!.state(input.managedRoot, trackedSkillPaths(index.stdout, head.stdout))
          let batch: string[] = []
          let length = 0
          for (const path of carried?.paths ?? []) {
            if (length + path.length > 4000 && batch.length) {
              await git(input.managedRoot, ['update-index', '--force-remove', '--', ...batch], env, 16 * 1024)
              batch = []; length = 0
            }
            batch.push(path); length += path.length + 3
          }
          if (batch.length) await git(input.managedRoot, ['update-index', '--force-remove', '--', ...batch], env, 16 * 1024)
        }
        const names = await git(
          input.managedRoot,
          ['diff', '--cached', '--name-status', '-z', '--find-renames', input.baseOid, '--', '.'],
          env,
          4 * 1024 * 1024,
        )
        if (names.truncated) throw new Error(hostMessage('reviewDiffPathInventoryExceedsTheSafeReadBudget'))
        const entries = parseNameStatus(names.stdout)
        if (entries.some(entry => !projectPath(entry.path) || (entry.previousPath !== undefined && !projectPath(entry.previousPath)))) {
          throw new Error(hostMessage('gitDiffReturnedAnUnsafeProjectRelativePath'))
        }
        const actual = changedPathSet(entries)
        if (actual.length !== expected.length || actual.some((path, index) => path !== expected[index])) {
          throw new ReviewDiffStaleError(hostMessage('reviewChangedFilesNoLongerMatchesTheIsolatedSnapshot'))
        }

        const files: WorktreeConsoleDiffFile[] = []
        let truncated = entries.length > REVIEW_DIFF_MAX_FILES
        const sliced = entries.slice(0, REVIEW_DIFF_MAX_FILES)
        // 逐文件 2 次 spawn 串行时最坏 400 次（会顶爆 SLOW 180s 超时）；
        // 按批并行取证，预算/截断折叠仍按原文件顺序逐个进行，语义不变。
        const REVIEW_DIFF_BATCH_SIZE = 8
        let stop = false
        for (let start = 0; start < sliced.length && !stop; start += REVIEW_DIFF_BATCH_SIZE) {
          const sampled = await Promise.all(sliced.slice(start, start + REVIEW_DIFF_BATCH_SIZE).map(async (entry) => {
            const numstat = await git(
              input.managedRoot,
              ['diff', '--cached', '--numstat', '-z', input.baseOid, '--', entry.path],
              env,
              32 * 1024,
            )
            const binary = numstat.stdout.toString('utf8').startsWith('-\t-\t')
            let patch: string | null = null
            let fileTruncated = false
            if (!binary) {
              const patchResult = await git(
                input.managedRoot,
                ['diff', '--cached', '--no-ext-diff', '--no-textconv', '--find-renames', input.baseOid, '--', entry.path],
                env,
                REVIEW_DIFF_MAX_PATCH_BYTES,
              )
              patch = patchResult.stdout.toString('utf8')
              fileTruncated = patchResult.truncated
            }
            return { entry, binary, patch, fileTruncated }
          }))
          for (const { entry, binary, patch, fileTruncated } of sampled) {
            const file: WorktreeConsoleDiffFile = {
              path: entry.path,
              ...(entry.previousPath === undefined ? {} : { previousPath: entry.previousPath }),
              status: binary ? 'binary' : entry.status,
              patch,
              truncated: fileTruncated,
            }
            let candidate: WorktreeConsoleReviewDiffResponse = {
              reviewId: input.reviewId,
              revision: input.revision,
              files: [...files, file],
              truncated: truncated || fileTruncated,
            }
            if (payloadBytes(candidate) > REVIEW_DIFF_MAX_PAYLOAD_BYTES) {
              truncated = true
              if (file.patch !== null) {
                const shell = { ...file, patch: '', truncated: true }
                const overhead = payloadBytes({ ...candidate, files: [...files, shell], truncated: true })
                const reduced = { ...shell, patch: utf8Prefix(file.patch, Math.max(0, REVIEW_DIFF_MAX_PAYLOAD_BYTES - overhead - 16)) }
                candidate = { ...candidate, files: [...files, reduced], truncated: true }
                if (payloadBytes(candidate) <= REVIEW_DIFF_MAX_PAYLOAD_BYTES) files.push(reduced)
              }
              stop = true
              break
            }
            files.push(file)
            if (fileTruncated) truncated = true
          }
        }
        return { reviewId: input.reviewId, revision: input.revision, files, truncated }
      } finally {
        await rm(tempRoot, { recursive: true, force: true })
      }
    },
  }
}

