class DefaultSessionCheckoutApplyEngine implements SessionCheckoutApplyEngine {
  private readonly plans = new Map<string, StoredPlan>()

  constructor(private readonly options: SessionCheckoutApplyEngineOptions) {}

  private captureSnapshot(
    checkoutPath: string,
    indexPath: string,
    objectDirectory: string | null,
    sourceObjects: string | null,
    excludes?: string[],
  ): Promise<CheckoutSnapshot> {
    return captureSnapshot(checkoutPath, indexPath, objectDirectory, sourceObjects, this.options.projectSkills, excludes)
  }

  async checkpoint(input: CheckpointInput): Promise<CheckpointResult> {
    const commitMessage = input.commitMessage.trim()
    if (!isValidCommitMessage(commitMessage) || !OID_PATTERN.test(input.expectedHeadOid) || !input.expectedFingerprint.trim()) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidCheckpointInput') } }
    }

    let tempRoot: string | null = null
    let adjacentIndex: string | null = null
    let indexLockMarker: string | null = null
    let preserveRecoveryEvidence = false
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'dsh-checkpoint-'))
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const projectPathPrefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (projectPathPrefix === null) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theCheckpointProjectDirectoryDoesNotBelongToThe') } }
      }
      const snapshot = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'checkpoint.index'), null, null)
      if (snapshot.headOid !== input.expectedHeadOid || snapshot.fingerprint !== input.expectedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeChangedAfterPreparingTheReviewTheCheckpointCannot') } }
      }
      const changedPaths = await changedTreePaths(isolatedGitRoot, snapshot.headOid, snapshot.treeOid, null, null)
      if (changedPaths.some((path) => !isProjectPath(path, projectPathPrefix))) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('worktreeContainsChangesOutsideTheProjectRootTheCheckpoint') } }
      }
      const changedFiles = changedPaths.map((path) => toProjectPath(path, projectPathPrefix)).sort()
      if (changedFiles.length === 0) {
        return { status: 'error', error: { code: 'operation_not_allowed', message: hostMessage('theCurrentCheckpointHasNoNewChangesToSave') } }
      }

      const commitOid = await createUserCommit(isolatedGitRoot, snapshot.treeOid, snapshot.headOid, commitMessage)
      await input.beforeCommit?.({ commitOid, parentOid: snapshot.headOid, indexTreeOid: snapshot.indexTreeOid, changedFiles })

      const finalIndexPath = join(tempRoot, 'clean.index')
      await prepareIndexFromPatch(isolatedGitRoot, finalIndexPath, commitOid, Buffer.alloc(0))
      const realIndexPath = await resolveIndexPath(isolatedGitRoot)
      const indexLockPath = `${realIndexPath}.lock`
      indexLockMarker = `${indexLockPath}.dsh-${commitOid}`
      await writeFile(indexLockMarker, `${commitOid}\n`, { flag: 'wx' })
      const indexLock = await open(indexLockPath, 'wx')
      adjacentIndex = indexLockPath
      await indexLock.close()
      await copyFile(finalIndexPath, adjacentIndex)

      await this.options.beforeFinalIsolatedValidation?.()
      const finalSnapshot = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'final-checkpoint.index'), null, null)
      if (finalSnapshot.headOid !== snapshot.headOid || finalSnapshot.fingerprint !== snapshot.fingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeChangedBeforeSavingTheCheckpointPrepareTheReview') } }
      }

      let headUpdated = false
      const headRef = snapshot.headRef
      const advanceHead = async (nextOid: string, previousOid: string): Promise<void> => {
        // A branch-attached worktree must advance the branch, never overwrite HEAD: `--no-deref` on
        // a symbolic HEAD would detach it and orphan the session branch the delivery commits to.
        if (headRef === null) {
          await runGit(isolatedGitRoot, ['update-ref', '--no-deref', 'HEAD', nextOid, previousOid])
          return
        }
        await runGit(isolatedGitRoot, ['update-ref', headRef, nextOid, previousOid])
      }
      try {
        await advanceHead(commitOid, snapshot.headOid)
        headUpdated = true
        await rename(adjacentIndex, realIndexPath)
        adjacentIndex = null
        await removeBestEffort(indexLockMarker)
        indexLockMarker = null
      } catch (error) {
        if (headUpdated) {
          try {
            await advanceHead(snapshot.headOid, commitOid)
          } catch (rollbackError) {
            preserveRecoveryEvidence = true
            return {
              status: 'error',
              error: {
                code: 'git_error',
                message: hostMessage('checkpointIndexWriteFailedAndHEADCouldNotBe', { p0: this.errorMessage(error), p1: this.errorMessage(rollbackError) }),
                recoveryState: 'uncertain',
              },
            }
          }
        }
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('checkpointWriteFailedAndWasRolledBack', { p0: this.errorMessage(error) }),
            recoveryState: 'unchanged',
          },
        }
      }

      try {
        await this.options.afterIsolatedWriteBeforeVerification?.()
        const completed = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'completed.index'), null, null)
        if (
          completed.headOid !== commitOid
          || completed.headRef !== snapshot.headRef
          || completed.headTreeOid !== snapshot.treeOid
          || completed.indexTreeOid !== snapshot.treeOid
          || completed.treeOid !== snapshot.treeOid
        ) {
          return {
            status: 'error',
            error: { code: 'git_error', message: hostMessage('checkpointWasWrittenButWorktreeDidNotReachA'), recoveryState: 'uncertain' },
          }
        }
        return {
          status: 'checkpointed',
          commitOid,
          parentOid: snapshot.headOid,
          changedFiles,
          isolatedFingerprint: completed.fingerprint,
        }
      } catch (error) {
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('cannotVerifyTheCheckpointAfterWritingTheEnvironmentMust', { p0: this.errorMessage(error) }),
            recoveryState: 'uncertain',
          },
        }
      }
    } catch (error) {
      const stale = isIndexLockContention(error)
      return {
        status: 'error',
        error: stale
          ? { code: 'stale_isolated', message: hostMessage('anotherGitOperationIsUpdatingTheWorktreeIndexRetry') }
          : { code: 'git_error', message: this.errorMessage(error) },
      }
    } finally {
      if (!preserveRecoveryEvidence) {
        await removeBestEffort(adjacentIndex)
        await removeBestEffort(indexLockMarker)
      }
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async recoverCheckpoint(input: { isolatedPath: string; commitOid: string; parentOid: string; expectedIndexTreeOid: string }): Promise<CheckpointRecoveryResult> {
    if (!OID_PATTERN.test(input.commitOid) || !OID_PATTERN.test(input.parentOid) || !OID_PATTERN.test(input.expectedIndexTreeOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidCheckpointRecoveryOID') } }
    }
    let tempRoot: string | null = null
    let ownedIndexLock: string | null = null
    let ownedLockMarker: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'dsh-checkpoint-recovery-'))
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const realIndexPath = await resolveIndexPath(isolatedGitRoot)
      const indexLockPath = `${realIndexPath}.lock`
      const indexLockMarker = `${indexLockPath}.dsh-${input.commitOid}`
      const targetTreeOid = stdoutText(await runGit(isolatedGitRoot, ['rev-parse', `${input.commitOid}^{tree}`]))
      const existingLock = await inspectIndexFileTree(isolatedGitRoot, indexLockPath)
      const markerOwned = await checkpointLockMarkerOwned(indexLockMarker, input.commitOid)
      const snapshot = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'current.index'), null, null)

      if (snapshot.headOid === input.parentOid) {
        if (existingLock.exists) {
          if (!markerOwned || (existingLock.treeOid !== null && existingLock.treeOid !== targetTreeOid)) {
            return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('cannotProveTheRemainingIndexLockBelongsToThe') } }
          }
          await unlink(indexLockPath)
        }
        if (markerOwned) await unlink(indexLockMarker)
        return { status: 'checkpoint_aborted', isolatedFingerprint: snapshot.fingerprint }
      }
      if (snapshot.headOid !== input.commitOid) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeHEADDoesNotMatchTheCheckpointBeingRecovered') } }
      }
      if (snapshot.treeOid !== snapshot.headTreeOid) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeHasNewChangesAfterCheckpointInterruptionTheIndex') } }
      }
      if (snapshot.indexTreeOid !== input.expectedIndexTreeOid && snapshot.indexTreeOid !== snapshot.headTreeOid) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('theIndexHasNewStagedChangesAfterCheckpointInterruption') } }
      }

      const cleanIndexPath = join(tempRoot, 'clean.index')
      await prepareIndexFromPatch(isolatedGitRoot, cleanIndexPath, input.commitOid, Buffer.alloc(0))
      if (existingLock.exists) {
        if (!markerOwned || (existingLock.treeOid !== null && existingLock.treeOid !== targetTreeOid)) {
          return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('theRemainingIndexLockDoesNotMatchTheCheckpoint') } }
        }
        if (existingLock.treeOid === null) await copyFile(cleanIndexPath, indexLockPath)
      } else {
        if (!markerOwned) {
          await writeFile(indexLockMarker, `${input.commitOid}\n`, { flag: 'wx' })
          ownedLockMarker = indexLockMarker
        }
        const indexLock = await open(indexLockPath, 'wx')
        ownedIndexLock = indexLockPath
        await indexLock.close()
        await copyFile(cleanIndexPath, indexLockPath)
      }

      await this.options.beforeFinalIsolatedValidation?.()
      const lockedSnapshot = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'locked-current.index'), null, null)
      if (
        lockedSnapshot.headOid !== snapshot.headOid
        || lockedSnapshot.fingerprint !== snapshot.fingerprint
        || (lockedSnapshot.indexTreeOid !== input.expectedIndexTreeOid && lockedSnapshot.indexTreeOid !== lockedSnapshot.headTreeOid)
      ) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeOrItsIndexChangedBeforeAcquiringTheCheckpoint') } }
      }
      await rename(indexLockPath, realIndexPath)
      ownedIndexLock = null
      await removeBestEffort(indexLockMarker)
      ownedLockMarker = null
      const completed = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'completed.index'), null, null)
      if (
        completed.headOid !== input.commitOid
        || completed.headRef !== snapshot.headRef
        || completed.indexTreeOid !== completed.headTreeOid
        || completed.treeOid !== completed.headTreeOid
      ) {
        return { status: 'error', error: { code: 'git_error', message: hostMessage('worktreeIsStillNotCleanAfterCheckpointIndexRecovery'), recoveryState: 'uncertain' } }
      }
      return { status: 'checkpoint_recovered', isolatedFingerprint: completed.fingerprint }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error), recoveryState: 'uncertain' } }
    } finally {
      await removeBestEffort(ownedIndexLock)
      await removeBestEffort(ownedLockMarker)
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async inspectReview(input: ApplyPlanInput): Promise<InspectReviewResult> {
    if (!OID_PATTERN.test(input.baseOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidSessionBaseOIDFormat') } }
    }
    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-review-snapshot-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const localGitRoot = await resolveGitRoot(input.localPath)
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const localObjects = await sourceObjectDirectory(localGitRoot)
      const isolatedObjects = await sourceObjectDirectory(isolatedGitRoot)
      if (!pathsMatch(localObjects, isolatedObjects)) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('localAndIsolatedDoNotBelongToTheSame') } }
      }
      const localPrefix = projectPrefix(localGitRoot, input.localPath)
      const isolatedPrefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (localPrefix === null || isolatedPrefix === null || localPrefix !== isolatedPrefix) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theLocalAndIsolatedProjectSubdirectoriesDoNotMatch') } }
      }
      await runGit(localGitRoot, ['cat-file', '-e', `${input.baseOid}^{commit}`])
      const isolated = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        localObjects,
      )
      const changedFiles = await changedTreePaths(
        isolatedGitRoot,
        input.baseOid,
        isolated.treeOid,
        objectDirectory,
        localObjects,
      )
      if (changedFiles.some((path) => !isProjectPath(path, localPrefix))) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootAReview') } }
      }
      return {
        status: 'ready',
        isolatedFingerprint: isolated.fingerprint,
        isolatedHeadOid: isolated.headOid,
        changedFiles: changedFiles.map((path) => toProjectPath(path, localPrefix)).sort(),
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  /**
   * 只看 Worktree 的评审快照：完全不读 Local（连它的 git 根都不解析），
   * 供会话分支交付在提交前判断「评审之后 Worktree 是否又改了」。
   */
  async reviewIsolated(input: ReviewIsolatedInput): Promise<ReviewIsolatedResult> {
    if (!OID_PATTERN.test(input.baseOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidSessionBaseOIDFormat') } }
    }
    let tempRoot: string | null = null
    try {
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const prefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (prefix === null) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theLocalAndIsolatedProjectSubdirectoriesDoNotMatch') } }
      }
      await runGit(isolatedGitRoot, ['cat-file', '-e', `${input.baseOid}^{commit}`])
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-isolated-review-'))
      const excludes = deliveryExcludePathspecs(input.excludePaths)
      const isolated = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        null,
        null,
        excludes,
      )
      const changedTree = await changedTreePaths(isolatedGitRoot, input.baseOid, isolated.treeOid, null, null)
      if (changedTree.some((path) => !isProjectPath(path, prefix))) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootAReview') } }
      }
      return {
        status: 'ready',
        isolatedFingerprint: isolated.fingerprint,
        isolatedHeadOid: isolated.headOid,
        changedFiles: changedTree.map((path) => toProjectPath(path, prefix)).sort(),
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  /**
   * 会话分支交付：把 Worktree 自身的工作区提交到它此刻检出的分支上。
   *
   * 与 `finish` 的根本差别是**完全不碰 Local**：不读 Local 的 HEAD/工作区/索引，
   * 不与它的未提交改动求三方合并，也不往它里面写补丁。会话分支就是交付目标，
   * 之后由用户或 `worktree_merge` 决定何时合出去。
   */
  async commitIsolated(input: CommitIsolatedInput): Promise<CommitIsolatedResult> {
    const branch = input.branchRef ?? null
    if (!OID_PATTERN.test(input.baseOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidSessionBaseOIDFormat') } }
    }
    const commitMessage = input.commitMessage.trim()
    if (!commitMessage) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('worktreeFinishCommitMessageRequired') } }
    }
    let tempRoot: string | null = null
    let committedOid: string | undefined
    try {
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const prefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (prefix === null) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theLocalAndIsolatedProjectSubdirectoriesDoNotMatch') } }
      }
      await runGit(isolatedGitRoot, ['cat-file', '-e', `${input.baseOid}^{commit}`])
      const excludes = deliveryExcludePathspecs(input.excludePaths)
      const headOid = stdoutText(await runGit(isolatedGitRoot, ['rev-parse', 'HEAD']))
      const headTreeOid = stdoutText(await runGit(isolatedGitRoot, ['rev-parse', `${headOid}^{tree}`]))
      const symbolic = await runGit(isolatedGitRoot, ['symbolic-ref', '--quiet', 'HEAD'], { allowedExitCodes: [0, 1] })
      const headRef = symbolic.exitCode === 0 ? stdoutText(symbolic) : null
      if (branch && headRef !== branch) {
        // 调用方保证先挂好会话分支；这里只做守门，避免把提交落到 detached HEAD 上丢线。
        return {
          status: 'error',
          error: {
            code: 'operation_not_allowed',
            message: hostMessage('theWorktreeIsNotOnTheSessionBranch', { p0: branch, p1: headRef ?? 'HEAD' }),
          },
        }
      }

      // 提交树取自「评审快照」同一条构造路径（临时 index）：它已经排除了宿主
      // 运行期产物与随会话携带的 Project Skills，交付提交因此不会把这些东西带进
      // 会话分支；直接用真实 index 做 `add -A` 会把它们一起提交。
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-commit-snapshot-'))
      const pending = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'pending.index'),
        null,
        null,
        excludes,
      )
      const created = pending.treeOid !== headTreeOid
      // 变更集范围在动 ref 之前就校验：提交一旦写进分支就不可撤回，
      // 任何能提前判死的检查都不该排在它后面。
      const pendingTree = await changedTreePaths(isolatedGitRoot, input.baseOid, pending.treeOid, null, null)
      if (pendingTree.some((path) => !isProjectPath(path, prefix))) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootAReview') } }
      }
      let commitOid = headOid
      if (created) {
        commitOid = await createUserCommit(isolatedGitRoot, pending.treeOid, headOid, commitMessage)
        // HEAD 通常是符号引用，默认 deref 会把分支一起推到新提交。
        await runGit(isolatedGitRoot, ['update-ref', 'HEAD', commitOid, headOid])
        // 从这里往下分支 ref 已经前进；再失败也不能让调用方当成交付没发生。
        committedOid = commitOid
        // index 归位到新 HEAD；工作区文件不动。
        await runGit(isolatedGitRoot, ['reset', '--quiet'])
      }

      // 提交后的干净快照：既作为清理阶段的 CAS 指纹，也用于报告变更集。
      const snapshot = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        null,
        null,
        excludes,
      )
      if (snapshot.headOid !== commitOid) {
        return {
          status: 'error',
          error: { code: 'git_error', message: hostMessage('theWorktreeHeadDidNotAdvanceToTheDeliveryCommit') },
          ...(committedOid === undefined ? {} : { committedOid }),
        }
      }
      const changedTree = await changedTreePaths(isolatedGitRoot, input.baseOid, snapshot.treeOid, null, null)
      if (changedTree.some((path) => !isProjectPath(path, prefix))) {
        return {
          status: 'error',
          error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootAReview') },
          ...(committedOid === undefined ? {} : { committedOid }),
        }
      }
      return {
        status: 'committed',
        commitOid,
        changedFiles: changedTree.map((path) => toProjectPath(path, prefix)).sort(),
        isolatedFingerprint: snapshot.fingerprint,
        branch: headRef,
        created,
      }
    } catch (error) {
      const message = this.errorMessage(error)
      const residue = committedOid === undefined ? {} : { committedOid }
      // git 没配好提交身份时给一句可执行的提示，而不是让模型盯着 "empty ident" 猜。
      if (/empty ident|who you are|please tell me who/i.test(message)) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('initialIdentityMissing') }, ...residue }
      }
      return { status: 'error', error: { code: 'git_error', message }, ...residue }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async preflight(input: ApplyPlanInput): Promise<ApplyPlanResult> {
    return this.calculatePlan(input, false)
  }

  async plan(input: ApplyPlanInput): Promise<ApplyPlanResult> {
    return this.calculatePlan(input, true)
  }

  private async calculatePlan(input: ApplyPlanInput, persistPlan: boolean): Promise<ApplyPlanResult> {
    if (!OID_PATTERN.test(input.baseOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidSessionBaseOIDFormat') } }
    }

    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-apply-plan-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const localGitRoot = await resolveGitRoot(input.localPath)
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const localObjects = await sourceObjectDirectory(localGitRoot)
      const isolatedObjects = await sourceObjectDirectory(isolatedGitRoot)
      if (!pathsMatch(localObjects, isolatedObjects)) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('localAndIsolatedDoNotBelongToTheSame') } }
      }
      const localPrefix = projectPrefix(localGitRoot, input.localPath)
      const isolatedPrefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (localPrefix === null || isolatedPrefix === null || localPrefix !== isolatedPrefix) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theLocalAndIsolatedProjectSubdirectoriesDoNotMatch') } }
      }
      await runGit(localGitRoot, ['cat-file', '-e', `${input.baseOid}^{commit}`])

      const local = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'local.index'),
        objectDirectory,
        localObjects,
      )
      const isolated = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        localObjects,
      )
      const effectiveBase = await selectEffectiveApplyBase(
        localGitRoot,
        input.baseOid,
        local.headOid,
        isolated.headOid,
      )
      const isolatedChangedPaths = await changedTreePaths(
        isolatedGitRoot,
        effectiveBase.oid,
        isolated.treeOid,
        objectDirectory,
        localObjects,
      )
      if (isolatedChangedPaths.some((path) => !isProjectPath(path, localPrefix))) {
        return {
          status: 'error',
          error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootApplyWas') },
        }
      }
      const merge = await computeMerge(
        tempRoot,
        localObjects,
        objectDirectory,
        effectiveBase.oid,
        local,
        isolated,
        localGitRoot,
        localPrefix,
      )
      const revision = randomUUID()
      if (merge.status === 'conflict') {
        return {
          status: 'conflict',
          revision,
          localFingerprint: local.fingerprint,
          isolatedFingerprint: isolated.fingerprint,
          effectiveBaseOid: effectiveBase.oid,
          baseStrategy: effectiveBase.strategy,
          localHeadOid: local.headOid,
          isolatedHeadOid: isolated.headOid,
          conflictingFiles: merge.conflictingFiles,
          ...(merge.conflictDetails ? { conflictDetails: merge.conflictDetails } : {}),
        }
      }

      const plan: ApplyPlan = {
        revision,
        localFingerprint: local.fingerprint,
        isolatedFingerprint: isolated.fingerprint,
        effectiveBaseOid: effectiveBase.oid,
        baseStrategy: effectiveBase.strategy,
        localHeadOid: local.headOid,
        localHeadRef: local.headRef,
        isolatedHeadOid: isolated.headOid,
        changedFiles: merge.changedFiles,
      }
      if (persistPlan) {
        // ponytail: this map must hold at most one stored plan per isolated
        // checkout — a freshly calculated plan supersedes the previous one for
        // the same path, so it cannot grow across repeated calculatePlan calls.
        for (const [storedRevision, storedPlan] of this.plans) {
          if (storedPlan.input.isolatedPath === input.isolatedPath) this.plans.delete(storedRevision)
        }
        this.plans.set(revision, {
          input: { ...input },
          patch: merge.patch,
          plan: { ...plan, changedFiles: [...plan.changedFiles] },
          scope: {
            isolatedGitRoot,
            localGitRoot,
            projectPrefix: localPrefix,
            sourceObjects: localObjects,
          },
        })
      }
      return { status: 'ready', plan: { ...plan, changedFiles: [...plan.changedFiles] } }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async apply(plan: ApplyPlan): Promise<ApplyResult> {
    const stored = this.plans.get(plan.revision)
    if (!stored || !planMatches(stored.plan, plan)) {
      return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theApplyPlanIsMissingAlreadyUsedOrModified') } }
    }

    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-apply-check-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(stored.scope.localGitRoot)
      if (!pathsMatch(sourceObjects, stored.scope.sourceObjects)) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theApplyPlanSGitRepositoryIdentityHasChanged') } }
      }
      const local = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (local.headOid !== stored.plan.localHeadOid || local.fingerprint !== stored.plan.localFingerprint) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedAfterPlanningRecalculateThePlan') } }
      }

      const isolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        sourceObjects,
      )
      if (isolated.headOid !== stored.plan.isolatedHeadOid || isolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }

      // 将已审核的 Isolated 最终状态写成无 ref 的内部 commit，供同一 checkout 后续 Apply 去重。
      // 使用独立 index，不改变 Isolated 的真实 staged/working tree。
      const persistentIsolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'persistent-isolated.index'),
        null,
        null,
      )
      if (persistentIsolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }
      const nextBaseOid = await createSnapshotCommit(
        stored.scope.isolatedGitRoot,
        persistentIsolated.treeOid,
        stored.plan.effectiveBaseOid,
        null,
        null,
        'Applied Isolated snapshot',
      )

      await this.options.beforeFinalLocalValidation?.()
      const finalLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'final-local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (finalLocal.headOid !== stored.plan.localHeadOid || finalLocal.fingerprint !== stored.plan.localFingerprint) {
        return {
          status: 'error',
          error: { code: 'stale_local', message: hostMessage('localChangedBeforeApplyWroteItsChangesRecalculateThe') },
        }
      }

      if (stored.patch.length > 0) {
        await runGit(stored.scope.localGitRoot, ['apply', '--binary', '--whitespace=nowarn'], { input: stored.patch })
      }
      this.plans.delete(plan.revision)
      return { status: 'applied', changedFiles: [...stored.plan.changedFiles], nextBaseOid }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async preview(
    plan: ApplyPlan,
    options: {
      previewId: string
      reviewId: string
      iteration: number
      beforeWrite?(receipt: PreviewReceipt): Promise<void>
    },
  ): Promise<PreviewResult> {
    const stored = this.plans.get(plan.revision)
    if (!stored || !planMatches(stored.plan, plan)) {
      return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('thePreviewPlanIsMissingAlreadyUsedOrModified') } }
    }
    if (!options.previewId.trim() || !options.reviewId.trim() || !Number.isSafeInteger(options.iteration) || options.iteration < 1) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidPreviewIdentity') } }
    }

    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-preview-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(stored.scope.localGitRoot)
      if (!pathsMatch(sourceObjects, stored.scope.sourceObjects)) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('thePreviewPlanSGitRepositoryIdentityHasChanged') } }
      }
      const local = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        local.headOid !== stored.plan.localHeadOid
        || local.headRef !== stored.plan.localHeadRef
        || local.fingerprint !== stored.plan.localFingerprint
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedAfterPlanningRecalculateThePlan') } }
      }
      const isolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        sourceObjects,
      )
      if (isolated.headOid !== stored.plan.isolatedHeadOid || isolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }

      const persistentLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'persistent-local.index'),
        null,
        null,
      )
      const persistentIsolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'persistent-isolated.index'),
        null,
        null,
      )
      if (
        persistentLocal.fingerprint !== stored.plan.localFingerprint
        || persistentIsolated.fingerprint !== stored.plan.isolatedFingerprint
      ) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('thePersistentPreviewSnapshotDoesNotMatchTheReviewed') } }
      }
      const previewWorkingTreeOid = await prepareIndexFromPatch(
        stored.scope.localGitRoot,
        join(tempRoot, 'preview-working.index'),
        persistentLocal.treeOid,
        stored.patch,
      )
      const isolatedSnapshotOid = await createSnapshotCommit(
        stored.scope.isolatedGitRoot,
        persistentIsolated.treeOid,
        stored.plan.effectiveBaseOid,
        null,
        null,
        'Previewed Isolated snapshot',
      )
      const preparedReceipt: PreviewReceipt = {
        previewId: options.previewId,
        reviewId: options.reviewId,
        iteration: options.iteration,
        previewedAt: Date.now(),
        configuredBaseOid: stored.input.baseOid,
        effectiveBaseOid: stored.plan.effectiveBaseOid,
        baseStrategy: stored.plan.baseStrategy,
        localHeadOid: persistentLocal.headOid,
        localHeadRef: persistentLocal.headRef,
        localFingerprintBefore: persistentLocal.fingerprint,
        localFingerprintPreview: '',
        localWorkingTreeOid: persistentLocal.treeOid,
        localIndexTreeOid: persistentLocal.indexTreeOid,
        previewWorkingTreeOid,
        isolatedHeadOid: persistentIsolated.headOid,
        isolatedFingerprint: persistentIsolated.fingerprint,
        isolatedSnapshotOid,
        changedFiles: [...stored.plan.changedFiles],
      }

      await this.options.beforeFinalLocalValidation?.()
      const finalLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'final-local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (finalLocal.headOid !== stored.plan.localHeadOid || finalLocal.fingerprint !== stored.plan.localFingerprint) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforePreviewWroteItsChangesRecalculateThe') } }
      }
      await options.beforeWrite?.(preparedReceipt)
      if (stored.patch.length > 0) {
        await runGit(stored.scope.localGitRoot, ['apply', '--binary', '--whitespace=nowarn'], { input: stored.patch })
      }
      const previewedLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'previewed-local.index'),
        null,
        null,
      )
      if (previewedLocal.treeOid !== previewWorkingTreeOid) {
        return {
          status: 'error',
          error: { code: 'git_error', message: hostMessage('theLocalSnapshotAfterPreviewDoesNotMatchThe') },
        }
      }

      this.plans.delete(plan.revision)
      const receipt: PreviewReceipt = {
        ...preparedReceipt,
        localFingerprintPreview: previewedLocal.fingerprint,
      }
      return { status: 'previewed', receipt, changedFiles: [...receipt.changedFiles] }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async assessPreviewRecovery(input: { localPath: string; receipt: PreviewReceipt }): Promise<PreviewRecoveryAssessment | ApplyErrorResult> {
    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-preview-recovery-preflight-'))
      const localGitRoot = await resolveGitRoot(input.localPath)
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(localGitRoot)
      const current = await this.captureSnapshot(localGitRoot, join(tempRoot, 'current.index'), objectDirectory, sourceObjects)
      const rollback = await prepareRollbackAssessment(tempRoot, sourceObjects, objectDirectory, localGitRoot, current, input.receipt)
      const finalize = await prepareFinalizeAssessment(tempRoot, sourceObjects, objectDirectory, localGitRoot, current, input.receipt)
      return {
        localFingerprint: current.fingerprint,
        localHeadOid: current.headOid,
        localHeadRef: current.headRef,
        localHeadTreeOid: current.headTreeOid,
        localIndexTreeOid: current.indexTreeOid,
        localWorkingTreeOid: current.treeOid,
        rollback,
        finalize,
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async rollback(input: {
    localPath: string
    receipt: PreviewReceipt
    beforeWrite?(): Promise<void>
  }): Promise<RollbackResult> {
    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-preview-rollback-'))
      const localGitRoot = await resolveGitRoot(input.localPath)
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(localGitRoot)
      const current = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'current.index'),
        objectDirectory,
        sourceObjects,
      )
      const assessment = await prepareRollbackAssessment(
        tempRoot,
        sourceObjects,
        objectDirectory,
        localGitRoot,
        current,
        input.receipt,
      )
      if (assessment.status === 'blocked') {
        return { status: 'error', error: { code: assessment.code, message: assessment.message } }
      }
      const rollbackPatch = await treePatch(
        localGitRoot,
        current.treeOid,
        assessment.targetTreeOid,
        objectDirectory,
        sourceObjects,
      )
      // Journal persistence may await registry I/O, so it must happen before the authoritative
      // final Local CAS. From the snapshot below to git apply there is no callback/yield seam.
      await input.beforeWrite?.()
      await this.options.beforeFinalLocalValidation?.()
      const finalLocal = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'final-local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        finalLocal.fingerprint !== current.fingerprint
        || finalLocal.headOid !== current.headOid
        || finalLocal.headRef !== current.headRef
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforePreviewRollbackRetry') } }
      }
      if (rollbackPatch.length > 0) {
        await runGit(localGitRoot, ['apply', '--binary', '--whitespace=nowarn'], { input: rollbackPatch })
      }
      let rolledBack: CheckoutSnapshot
      try {
        await this.options.afterLocalWriteBeforeVerification?.()
        rolledBack = await this.captureSnapshot(
          localGitRoot,
          join(tempRoot, 'rolled-back.index'),
          null,
          null,
        )
      } catch (error) {
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('cannotVerifyAfterWritingPreviewRollbackTheEnvironmentMust', { p0: this.errorMessage(error) }),
            recoveryState: 'uncertain',
          },
        }
      }
      const expectedFingerprint = snapshotFingerprint(
        current.headOid,
        current.headRef,
        current.indexEntries,
        assessment.targetTreeOid,
      )
      if (
        rolledBack.headOid !== current.headOid
        || rolledBack.headRef !== current.headRef
        || rolledBack.indexTreeOid !== current.indexTreeOid
        || rolledBack.treeOid !== assessment.targetTreeOid
        || rolledBack.fingerprint !== expectedFingerprint
      ) {
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('theLocalSnapshotAfterPreviewRollbackDoesNotMatch'),
            recoveryState: 'uncertain',
          },
        }
      }
      return { status: 'preview_rolled_back', changedFiles: [...input.receipt.changedFiles] }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async finalize(input: {
    localPath: string
    receipt: PreviewReceipt
    commitMessage: string
    beforeCommit?(commitOid: string): Promise<void>
  }): Promise<FinishResult> {
    const commitMessage = input.commitMessage.trim()
    if (!isValidCommitMessage(commitMessage)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theCommitMessageMustBeNonemptyAndContainNoNul') } }
    }

    let tempRoot: string | null = null
    let ownedIndexLock: string | null = null
    let backupIndex: string | null = null
    let preserveBackup = false
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-preview-finalize-'))
      const localGitRoot = await resolveGitRoot(input.localPath)
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(localGitRoot)
      const current = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'current.index'),
        objectDirectory,
        sourceObjects,
      )
      const realIndexPath = await resolveIndexPath(localGitRoot)
      const originalIndexBytes = await readFile(realIndexPath)
      const assessment = await prepareFinalizeAssessment(
        tempRoot,
        sourceObjects,
        objectDirectory,
        localGitRoot,
        current,
        input.receipt,
      )
      if (assessment.status === 'blocked') {
        return { status: 'error', error: { code: assessment.code, message: assessment.message } }
      }

      if (!assessment.commitRequired) {
        await this.options.beforeFinalLocalValidation?.()
        const finalLocal = await this.captureSnapshot(
          localGitRoot,
          join(tempRoot, 'final-empty.index'),
          objectDirectory,
          sourceObjects,
        )
        if (
          finalLocal.headOid !== current.headOid
          || finalLocal.headRef !== current.headRef
          || finalLocal.fingerprint !== current.fingerprint
        ) {
          return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeFinalizingPreviewRetry') } }
        }
        return {
          status: 'finished',
          changedFiles: [],
          commitOid: null,
          nextBaseOid: input.receipt.isolatedSnapshotOid,
        }
      }

      const taskPatch = await treePatch(
        localGitRoot,
        current.headTreeOid,
        assessment.taskTreeOid,
        objectDirectory,
        sourceObjects,
      )
      const finalIndexPatch = await treePatch(
        localGitRoot,
        assessment.taskTreeOid,
        assessment.finalIndexTreeOid,
        objectDirectory,
        sourceObjects,
      )
      const actualTaskTreeOid = await prepareIndexFromPatch(
        localGitRoot,
        join(tempRoot, 'task.index'),
        current.headOid,
        taskPatch,
      )
      if (actualTaskTreeOid !== assessment.taskTreeOid) {
        return { status: 'error', error: { code: 'git_error', message: hostMessage('thePreviewTaskCommitTreeDoesNotMatchThe') } }
      }
      const commitOid = await createUserCommit(localGitRoot, actualTaskTreeOid, current.headOid, commitMessage)
      const finalIndexPath = join(tempRoot, 'final.index')
      const actualFinalIndexTreeOid = await prepareIndexFromPatch(
        localGitRoot,
        finalIndexPath,
        commitOid,
        finalIndexPatch,
      )
      if (actualFinalIndexTreeOid !== assessment.finalIndexTreeOid) {
        return { status: 'error', error: { code: 'git_error', message: hostMessage('thePreviewFinalIndexTreeDoesNotMatchThe') } }
      }
      const expectedIndexEntries = (
        await runGit(localGitRoot, ['ls-files', '--stage', '-z'], { env: { GIT_INDEX_FILE: finalIndexPath } })
      ).stdout
      const intendedIndexBytes = await readFile(finalIndexPath)
      const expectedFingerprint = snapshotFingerprint(
        commitOid,
        current.headRef,
        expectedIndexEntries,
        assessment.expectedWorkingTreeOid,
      )
      await input.beforeCommit?.(commitOid)

      const branchRef = current.headRef
      if (!branchRef?.startsWith('refs/heads/')) {
        return { status: 'error', error: { code: 'operation_not_allowed', message: hostMessage('localIsNotOnANormalBranchATask') } }
      }
      backupIndex = `${realIndexPath}.domi-backup-${randomUUID()}`
      await copyFile(realIndexPath, backupIndex)
      await this.options.beforeFinalLocalValidation?.()
      try {
        // Use Git's canonical index.lock protocol. While this lock exists, concurrent git add/reset
        // cannot mutate the real index between the authoritative snapshot and our atomic replacement.
        ownedIndexLock = await writeIndexLock(realIndexPath, intendedIndexBytes)
      } catch (error) {
        if (isIndexLockContention(error)) {
          return { status: 'error', error: { code: 'stale_local', message: hostMessage('anotherGitOperationIsUpdatingTheLocalIndexRetry') } }
        }
        throw error
      }
      const finalLocal = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'final-local.index'),
        objectDirectory,
        sourceObjects,
      )
      const finalIndexBytes = await readFile(realIndexPath)
      if (
        finalLocal.headOid !== current.headOid
        || finalLocal.headRef !== current.headRef
        || finalLocal.fingerprint !== current.fingerprint
        || !finalIndexBytes.equals(originalIndexBytes)
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeThePreviewCommitWasWrittenRetry') } }
      }

      let refUpdated = false
      let indexReplaced = false
      let writeError: unknown = null
      try {
        await runGit(localGitRoot, ['update-ref', branchRef, commitOid, current.headOid])
        refUpdated = true
        await rename(ownedIndexLock, realIndexPath)
        ownedIndexLock = null
        indexReplaced = true
      } catch (error) {
        writeError = error
      }

      if (!writeError) {
        try {
          await this.options.afterLocalWriteBeforeVerification?.()
          const committed = await this.captureSnapshot(
            localGitRoot,
            join(tempRoot, 'committed.index'),
            null,
            null,
          )
          const committedIndexBytes = await readFile(realIndexPath)
          if (
            committed.headOid === commitOid
            && committed.headRef === branchRef
            && committed.indexTreeOid === assessment.finalIndexTreeOid
            && committed.treeOid === assessment.expectedWorkingTreeOid
            && committed.fingerprint === expectedFingerprint
            && committedIndexBytes.equals(intendedIndexBytes)
          ) {
            await removeBestEffort(backupIndex)
            backupIndex = null
            return {
              status: 'finished',
              changedFiles: [...input.receipt.changedFiles],
              commitOid,
              nextBaseOid: input.receipt.isolatedSnapshotOid,
            }
          }
          writeError = new Error(hostMessage('previewCommitVerificationFailedAfterWriting'))
        } catch (error) {
          writeError = error
        }
      }

      const rollbackErrors: string[] = []
      if (refUpdated && !indexReplaced && ownedIndexLock) {
        // The ref moved but the index replacement did not. We still own index.lock, so no Git
        // index writer can race the ref CAS rollback; the real index is already the original one.
        try {
          await runGit(localGitRoot, ['update-ref', branchRef, current.headOid, commitOid])
          refUpdated = false
          await removeBestEffort(ownedIndexLock)
          ownedIndexLock = null
        } catch (error) {
          rollbackErrors.push(`ref: ${this.errorMessage(error)}`)
        }
      } else if (refUpdated && indexReplaced && backupIndex) {
        // Compensation is itself a CAS transaction. Never restore the old backup over an index
        // that changed after Domi's write; preserve both the user's index and our backup instead.
        try {
          const backupBytes = await readFile(backupIndex)
          ownedIndexLock = await writeIndexLock(realIndexPath, backupBytes)
          const currentIndexBytes = await readFile(realIndexPath)
          if (!currentIndexBytes.equals(intendedIndexBytes)) {
            rollbackErrors.push(hostMessage('indexLocalIndexChangedAfterPreviewWroteItsChanges'))
          } else {
            await runGit(localGitRoot, ['update-ref', branchRef, current.headOid, commitOid])
            refUpdated = false
            await rename(ownedIndexLock, realIndexPath)
            ownedIndexLock = null
            indexReplaced = false
          }
        } catch (error) {
          rollbackErrors.push(`compensation: ${this.errorMessage(error)}`)
        }
      } else if (refUpdated) {
        rollbackErrors.push(hostMessage('refVerifiableIndexCompensationEvidenceIsMissingPartialRollback'))
      }

      let restored = false
      if (rollbackErrors.length === 0) {
        try {
          const restoredLocal = await this.captureSnapshot(
            localGitRoot,
            join(tempRoot, 'restored.index'),
            null,
            null,
          )
          const restoredIndexBytes = await readFile(realIndexPath)
          restored = restoredLocal.headOid === current.headOid
            && restoredLocal.headRef === current.headRef
            && restoredLocal.indexTreeOid === current.indexTreeOid
            && restoredLocal.treeOid === current.treeOid
            && restoredLocal.fingerprint === current.fingerprint
            && restoredIndexBytes.equals(originalIndexBytes)
        } catch (error) {
          rollbackErrors.push(`verification: ${this.errorMessage(error)}`)
        }
      }
      if (restored) {
        await removeBestEffort(backupIndex)
        backupIndex = null
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('thePreviewCommitWriteCouldNotBeVerifiedAnd', { p0: this.errorMessage(writeError) }),
            recoveryState: 'unchanged',
          },
        }
      }

      preserveBackup = true
      const rollbackDetail = rollbackErrors.length > 0 ? `；${rollbackErrors.join('；')}` : ''
      return {
        status: 'error',
        error: {
          code: 'git_error',
          message: hostMessage('cannotProveSuccessOrCompleteRollbackAfterWritingThe', { p0: this.errorMessage(writeError), p1: rollbackDetail, p2: backupIndex ?? 'unknown' }),
          recoveryState: 'uncertain',
        },
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      await removeBestEffort(ownedIndexLock)
      if (!preserveBackup) await removeBestEffort(backupIndex)
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  async finish(plan: ApplyPlan, options: { commitMessage: string }): Promise<FinishResult> {
    const stored = this.plans.get(plan.revision)
    if (!stored || !planMatches(stored.plan, plan)) {
      return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theFinishPlanIsMissingAlreadyUsedOrModified') } }
    }
    const commitMessage = options.commitMessage.trim()
    if (!isValidCommitMessage(commitMessage)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theCommitMessageMustBeNonemptyAndContainNoNul') } }
    }
    if (!stored.plan.localHeadRef?.startsWith('refs/heads/')) {
      return {
        status: 'error',
        error: { code: 'operation_not_allowed', message: hostMessage('localIsNotOnANormalBranchATask') },
      }
    }

    let tempRoot: string | null = null
    let ownedIndexLock: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-finish-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(stored.scope.localGitRoot)
      if (!pathsMatch(sourceObjects, stored.scope.sourceObjects)) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theFinishPlanSGitRepositoryIdentityHasChanged') } }
      }

      const local = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        local.headOid !== stored.plan.localHeadOid
        || local.headRef !== stored.plan.localHeadRef
        || local.fingerprint !== stored.plan.localFingerprint
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedAfterPlanningRecalculateThePlan') } }
      }
      const isolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        sourceObjects,
      )
      if (isolated.headOid !== stored.plan.isolatedHeadOid || isolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }

      const merge = await computeMerge(
        tempRoot,
        sourceObjects,
        objectDirectory,
        stored.plan.effectiveBaseOid,
        local,
        isolated,
        stored.scope.localGitRoot,
        stored.scope.projectPrefix,
      )
      if (merge.status === 'conflict') {
        return {
          status: 'error',
          error: { code: 'invalid_plan', message: hostMessage('finishRevalidationFoundConflictsInconsistentWithTheReviewedPlan') },
        }
      }
      if (
        merge.changedFiles.length !== stored.plan.changedFiles.length
        || merge.changedFiles.some((path, index) => path !== stored.plan.changedFiles[index])
      ) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theFileSetChangedDuringFinishRevalidation') } }
      }

      const persistentIsolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'persistent-isolated.index'),
        null,
        null,
      )
      if (persistentIsolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }
      const nextBaseOid = await createSnapshotCommit(
        stored.scope.isolatedGitRoot,
        persistentIsolated.treeOid,
        stored.plan.effectiveBaseOid,
        null,
        null,
        'Finished Isolated snapshot',
      )

      if (merge.changedFiles.length === 0) {
        await this.options.beforeFinalLocalValidation?.()
        const finalLocal = await this.captureSnapshot(
          stored.scope.localGitRoot,
          join(tempRoot, 'final-local.index'),
          objectDirectory,
          sourceObjects,
        )
        if (finalLocal.fingerprint !== stored.plan.localFingerprint) {
          return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeFinishRecalculateThePlan') } }
        }
        this.plans.delete(plan.revision)
        return { status: 'finished', changedFiles: [], commitOid: null, nextBaseOid }
      }

      // C = H + (M - L)：把任务增量从完整 Local 快照 L 中剥离，重放到旧 HEAD H。
      const taskTree = await computeTreeMerge(
        tempRoot,
        sourceObjects,
        objectDirectory,
        stored.scope.localGitRoot,
        'finish-task-isolation',
        local.treeOid,
        local.headTreeOid,
        merge.mergedTreeOid,
      )
      if (taskTree.status === 'conflict') {
        return {
          status: 'error',
          error: {
            code: 'commit_isolation_conflict',
            message: hostMessage('taskChangesCannotBeReliablySeparatedFromExistingLocal', { p0: taskTree.conflictingFiles.join('、') }),
          },
        }
      }

      // S' = C + (S - H)：在任务提交 C 上恢复用户原有 staged 状态。
      const finalIndexTree = await computeTreeMerge(
        tempRoot,
        sourceObjects,
        objectDirectory,
        stored.scope.localGitRoot,
        'finish-index-preservation',
        local.headTreeOid,
        taskTree.treeOid,
        local.indexTreeOid,
      )
      if (finalIndexTree.status === 'conflict') {
        return {
          status: 'error',
          error: {
            code: 'commit_isolation_conflict',
            message: hostMessage('theTaskCommitCannotBeReliablySeparatedFromExisting', { p0: finalIndexTree.conflictingFiles.join('、') }),
          },
        }
      }

      const taskPatch = await treePatch(
        stored.scope.localGitRoot,
        local.headTreeOid,
        taskTree.treeOid,
        objectDirectory,
        sourceObjects,
      )
      const finalIndexPatch = await treePatch(
        stored.scope.localGitRoot,
        taskTree.treeOid,
        finalIndexTree.treeOid,
        objectDirectory,
        sourceObjects,
      )
      const taskIndexPath = join(tempRoot, 'task-commit.index')
      const actualTaskTreeOid = await prepareIndexFromPatch(
        stored.scope.localGitRoot,
        taskIndexPath,
        local.headOid,
        taskPatch,
      )
      const commitOid = await createUserCommit(
        stored.scope.localGitRoot,
        actualTaskTreeOid,
        local.headOid,
        commitMessage,
      )
      const finalIndexPath = join(tempRoot, 'preserved-local.index')
      await prepareIndexFromPatch(
        stored.scope.localGitRoot,
        finalIndexPath,
        commitOid,
        finalIndexPatch,
      )

      await this.options.beforeFinalLocalValidation?.()
      const finalLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'final-local-validation.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        finalLocal.headOid !== stored.plan.localHeadOid
        || finalLocal.headRef !== stored.plan.localHeadRef
        || finalLocal.fingerprint !== stored.plan.localFingerprint
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeFinishWroteItsChangesRecalculateThe') } }
      }

      const realIndexPath = await resolveIndexPath(stored.scope.localGitRoot)
      // Git 的 index.lock 协议：持锁期间并发 git add/reset 无法改写真实 index，
      // 校验→打补丁→update-ref→换 index 在同一把锁内完成（与 finalize 对齐）。
      try {
        ownedIndexLock = await writeIndexLock(realIndexPath, await readFile(finalIndexPath))
      } catch (error) {
        if (isIndexLockContention(error)) {
          return { status: 'error', error: { code: 'stale_local', message: hostMessage('anotherGitOperationIsUpdatingTheLocalIndexRetry') } }
        }
        throw error
      }
      const lockedLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'locked-local-validation.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        lockedLocal.headOid !== stored.plan.localHeadOid
        || lockedLocal.headRef !== stored.plan.localHeadRef
        || lockedLocal.fingerprint !== stored.plan.localFingerprint
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeFinishWroteItsChangesRecalculateThe') } }
      }

      let worktreePatched = false
      let refUpdated = false
      try {
        if (merge.patch.length > 0) {
          await runGit(stored.scope.localGitRoot, ['apply', '--binary', '--whitespace=nowarn'], { input: merge.patch })
          worktreePatched = true
        }
        await runGit(stored.scope.localGitRoot, [
          'update-ref',
          stored.plan.localHeadRef,
          commitOid,
          local.headOid,
        ])
        refUpdated = true
        await rename(ownedIndexLock, realIndexPath)
        ownedIndexLock = null
      } catch (error) {
        const rollbackErrors: string[] = []
        if (refUpdated) {
          try {
            await runGit(stored.scope.localGitRoot, [
              'update-ref',
              stored.plan.localHeadRef,
              local.headOid,
              commitOid,
            ])
          } catch (rollbackError) {
            rollbackErrors.push(`ref: ${this.errorMessage(rollbackError)}`)
          }
        }
        if (worktreePatched) {
          try {
            await runGit(stored.scope.localGitRoot, ['apply', '-R', '--binary', '--whitespace=nowarn'], { input: merge.patch })
          } catch (rollbackError) {
            rollbackErrors.push(`worktree: ${this.errorMessage(rollbackError)}`)
          }
        }
        const detail = this.errorMessage(error)
        if (rollbackErrors.length > 0) {
          return {
            status: 'error',
            error: {
              code: 'git_error',
              message: hostMessage('finishWriteFailedAndCompleteRollbackCouldNotBe', { p0: detail, p1: rollbackErrors.join('；') }),
            },
          }
        }
        return { status: 'error', error: { code: 'git_error', message: hostMessage('finishWriteFailedAndWasRolledBack', { p0: detail }) } }
      }

      this.plans.delete(plan.revision)
      return {
        status: 'finished',
        changedFiles: [...stored.plan.changedFiles],
        commitOid,
        nextBaseOid,
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      await removeBestEffort(ownedIndexLock)
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

  private errorMessage(error: unknown): string {
    if (error instanceof GitCommandFailure) {
      return hostMessage('gitOperationFailed', { p0: error.args[0] ?? 'unknown', p1: error.message })
    }
    return error instanceof Error ? error.message : hostMessage('unknownGitError')
  }

  private async cleanup(path: string): Promise<void> {
    try {
      await rm(path, { recursive: true, force: true, maxRetries: 2 })
    } catch (error) {
      // 清理失败不能掩盖 plan/apply 的主结果。
      console.warn(hostMessage('tempDirectoryCleanupFailed'), error)
    }
  }
}

private captureSnapshot(
    checkoutPath: string,
    indexPath: string,
    objectDirectory: string | null,
    sourceObjects: string | null,
    excludes?: string[],
  ): Promise<CheckoutSnapshot> {
    return captureSnapshot(checkoutPath, indexPath, objectDirectory, sourceObjects, this.options.projectSkills, excludes)
  }

async checkpoint(input: CheckpointInput): Promise<CheckpointResult> {
    const commitMessage = input.commitMessage.trim()
    if (!isValidCommitMessage(commitMessage) || !OID_PATTERN.test(input.expectedHeadOid) || !input.expectedFingerprint.trim()) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidCheckpointInput') } }
    }

    let tempRoot: string | null = null
    let adjacentIndex: string | null = null
    let indexLockMarker: string | null = null
    let preserveRecoveryEvidence = false
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'dsh-checkpoint-'))
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const projectPathPrefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (projectPathPrefix === null) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theCheckpointProjectDirectoryDoesNotBelongToThe') } }
      }
      const snapshot = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'checkpoint.index'), null, null)
      if (snapshot.headOid !== input.expectedHeadOid || snapshot.fingerprint !== input.expectedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeChangedAfterPreparingTheReviewTheCheckpointCannot') } }
      }
      const changedPaths = await changedTreePaths(isolatedGitRoot, snapshot.headOid, snapshot.treeOid, null, null)
      if (changedPaths.some((path) => !isProjectPath(path, projectPathPrefix))) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('worktreeContainsChangesOutsideTheProjectRootTheCheckpoint') } }
      }
      const changedFiles = changedPaths.map((path) => toProjectPath(path, projectPathPrefix)).sort()
      if (changedFiles.length === 0) {
        return { status: 'error', error: { code: 'operation_not_allowed', message: hostMessage('theCurrentCheckpointHasNoNewChangesToSave') } }
      }

      const commitOid = await createUserCommit(isolatedGitRoot, snapshot.treeOid, snapshot.headOid, commitMessage)
      await input.beforeCommit?.({ commitOid, parentOid: snapshot.headOid, indexTreeOid: snapshot.indexTreeOid, changedFiles })

      const finalIndexPath = join(tempRoot, 'clean.index')
      await prepareIndexFromPatch(isolatedGitRoot, finalIndexPath, commitOid, Buffer.alloc(0))
      const realIndexPath = await resolveIndexPath(isolatedGitRoot)
      const indexLockPath = `${realIndexPath}.lock`
      indexLockMarker = `${indexLockPath}.dsh-${commitOid}`
      await writeFile(indexLockMarker, `${commitOid}\n`, { flag: 'wx' })
      const indexLock = await open(indexLockPath, 'wx')
      adjacentIndex = indexLockPath
      await indexLock.close()
      await copyFile(finalIndexPath, adjacentIndex)

      await this.options.beforeFinalIsolatedValidation?.()
      const finalSnapshot = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'final-checkpoint.index'), null, null)
      if (finalSnapshot.headOid !== snapshot.headOid || finalSnapshot.fingerprint !== snapshot.fingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeChangedBeforeSavingTheCheckpointPrepareTheReview') } }
      }

      let headUpdated = false
      const headRef = snapshot.headRef
      const advanceHead = async (nextOid: string, previousOid: string): Promise<void> => {
        // A branch-attached worktree must advance the branch, never overwrite HEAD: `--no-deref` on
        // a symbolic HEAD would detach it and orphan the session branch the delivery commits to.
        if (headRef === null) {
          await runGit(isolatedGitRoot, ['update-ref', '--no-deref', 'HEAD', nextOid, previousOid])
          return
        }
        await runGit(isolatedGitRoot, ['update-ref', headRef, nextOid, previousOid])
      }
      try {
        await advanceHead(commitOid, snapshot.headOid)
        headUpdated = true
        await rename(adjacentIndex, realIndexPath)
        adjacentIndex = null
        await removeBestEffort(indexLockMarker)
        indexLockMarker = null
      } catch (error) {
        if (headUpdated) {
          try {
            await advanceHead(snapshot.headOid, commitOid)
          } catch (rollbackError) {
            preserveRecoveryEvidence = true
            return {
              status: 'error',
              error: {
                code: 'git_error',
                message: hostMessage('checkpointIndexWriteFailedAndHEADCouldNotBe', { p0: this.errorMessage(error), p1: this.errorMessage(rollbackError) }),
                recoveryState: 'uncertain',
              },
            }
          }
        }
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('checkpointWriteFailedAndWasRolledBack', { p0: this.errorMessage(error) }),
            recoveryState: 'unchanged',
          },
        }
      }

      try {
        await this.options.afterIsolatedWriteBeforeVerification?.()
        const completed = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'completed.index'), null, null)
        if (
          completed.headOid !== commitOid
          || completed.headRef !== snapshot.headRef
          || completed.headTreeOid !== snapshot.treeOid
          || completed.indexTreeOid !== snapshot.treeOid
          || completed.treeOid !== snapshot.treeOid
        ) {
          return {
            status: 'error',
            error: { code: 'git_error', message: hostMessage('checkpointWasWrittenButWorktreeDidNotReachA'), recoveryState: 'uncertain' },
          }
        }
        return {
          status: 'checkpointed',
          commitOid,
          parentOid: snapshot.headOid,
          changedFiles,
          isolatedFingerprint: completed.fingerprint,
        }
      } catch (error) {
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('cannotVerifyTheCheckpointAfterWritingTheEnvironmentMust', { p0: this.errorMessage(error) }),
            recoveryState: 'uncertain',
          },
        }
      }
    } catch (error) {
      const stale = isIndexLockContention(error)
      return {
        status: 'error',
        error: stale
          ? { code: 'stale_isolated', message: hostMessage('anotherGitOperationIsUpdatingTheWorktreeIndexRetry') }
          : { code: 'git_error', message: this.errorMessage(error) },
      }
    } finally {
      if (!preserveRecoveryEvidence) {
        await removeBestEffort(adjacentIndex)
        await removeBestEffort(indexLockMarker)
      }
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async recoverCheckpoint(input: { isolatedPath: string; commitOid: string; parentOid: string; expectedIndexTreeOid: string }): Promise<CheckpointRecoveryResult> {
    if (!OID_PATTERN.test(input.commitOid) || !OID_PATTERN.test(input.parentOid) || !OID_PATTERN.test(input.expectedIndexTreeOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidCheckpointRecoveryOID') } }
    }
    let tempRoot: string | null = null
    let ownedIndexLock: string | null = null
    let ownedLockMarker: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'dsh-checkpoint-recovery-'))
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const realIndexPath = await resolveIndexPath(isolatedGitRoot)
      const indexLockPath = `${realIndexPath}.lock`
      const indexLockMarker = `${indexLockPath}.dsh-${input.commitOid}`
      const targetTreeOid = stdoutText(await runGit(isolatedGitRoot, ['rev-parse', `${input.commitOid}^{tree}`]))
      const existingLock = await inspectIndexFileTree(isolatedGitRoot, indexLockPath)
      const markerOwned = await checkpointLockMarkerOwned(indexLockMarker, input.commitOid)
      const snapshot = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'current.index'), null, null)

      if (snapshot.headOid === input.parentOid) {
        if (existingLock.exists) {
          if (!markerOwned || (existingLock.treeOid !== null && existingLock.treeOid !== targetTreeOid)) {
            return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('cannotProveTheRemainingIndexLockBelongsToThe') } }
          }
          await unlink(indexLockPath)
        }
        if (markerOwned) await unlink(indexLockMarker)
        return { status: 'checkpoint_aborted', isolatedFingerprint: snapshot.fingerprint }
      }
      if (snapshot.headOid !== input.commitOid) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeHEADDoesNotMatchTheCheckpointBeingRecovered') } }
      }
      if (snapshot.treeOid !== snapshot.headTreeOid) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeHasNewChangesAfterCheckpointInterruptionTheIndex') } }
      }
      if (snapshot.indexTreeOid !== input.expectedIndexTreeOid && snapshot.indexTreeOid !== snapshot.headTreeOid) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('theIndexHasNewStagedChangesAfterCheckpointInterruption') } }
      }

      const cleanIndexPath = join(tempRoot, 'clean.index')
      await prepareIndexFromPatch(isolatedGitRoot, cleanIndexPath, input.commitOid, Buffer.alloc(0))
      if (existingLock.exists) {
        if (!markerOwned || (existingLock.treeOid !== null && existingLock.treeOid !== targetTreeOid)) {
          return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('theRemainingIndexLockDoesNotMatchTheCheckpoint') } }
        }
        if (existingLock.treeOid === null) await copyFile(cleanIndexPath, indexLockPath)
      } else {
        if (!markerOwned) {
          await writeFile(indexLockMarker, `${input.commitOid}\n`, { flag: 'wx' })
          ownedLockMarker = indexLockMarker
        }
        const indexLock = await open(indexLockPath, 'wx')
        ownedIndexLock = indexLockPath
        await indexLock.close()
        await copyFile(cleanIndexPath, indexLockPath)
      }

      await this.options.beforeFinalIsolatedValidation?.()
      const lockedSnapshot = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'locked-current.index'), null, null)
      if (
        lockedSnapshot.headOid !== snapshot.headOid
        || lockedSnapshot.fingerprint !== snapshot.fingerprint
        || (lockedSnapshot.indexTreeOid !== input.expectedIndexTreeOid && lockedSnapshot.indexTreeOid !== lockedSnapshot.headTreeOid)
      ) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('worktreeOrItsIndexChangedBeforeAcquiringTheCheckpoint') } }
      }
      await rename(indexLockPath, realIndexPath)
      ownedIndexLock = null
      await removeBestEffort(indexLockMarker)
      ownedLockMarker = null
      const completed = await this.captureSnapshot(isolatedGitRoot, join(tempRoot, 'completed.index'), null, null)
      if (
        completed.headOid !== input.commitOid
        || completed.headRef !== snapshot.headRef
        || completed.indexTreeOid !== completed.headTreeOid
        || completed.treeOid !== completed.headTreeOid
      ) {
        return { status: 'error', error: { code: 'git_error', message: hostMessage('worktreeIsStillNotCleanAfterCheckpointIndexRecovery'), recoveryState: 'uncertain' } }
      }
      return { status: 'checkpoint_recovered', isolatedFingerprint: completed.fingerprint }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error), recoveryState: 'uncertain' } }
    } finally {
      await removeBestEffort(ownedIndexLock)
      await removeBestEffort(ownedLockMarker)
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async inspectReview(input: ApplyPlanInput): Promise<InspectReviewResult> {
    if (!OID_PATTERN.test(input.baseOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidSessionBaseOIDFormat') } }
    }
    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-review-snapshot-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const localGitRoot = await resolveGitRoot(input.localPath)
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const localObjects = await sourceObjectDirectory(localGitRoot)
      const isolatedObjects = await sourceObjectDirectory(isolatedGitRoot)
      if (!pathsMatch(localObjects, isolatedObjects)) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('localAndIsolatedDoNotBelongToTheSame') } }
      }
      const localPrefix = projectPrefix(localGitRoot, input.localPath)
      const isolatedPrefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (localPrefix === null || isolatedPrefix === null || localPrefix !== isolatedPrefix) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theLocalAndIsolatedProjectSubdirectoriesDoNotMatch') } }
      }
      await runGit(localGitRoot, ['cat-file', '-e', `${input.baseOid}^{commit}`])
      const isolated = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        localObjects,
      )
      const changedFiles = await changedTreePaths(
        isolatedGitRoot,
        input.baseOid,
        isolated.treeOid,
        objectDirectory,
        localObjects,
      )
      if (changedFiles.some((path) => !isProjectPath(path, localPrefix))) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootAReview') } }
      }
      return {
        status: 'ready',
        isolatedFingerprint: isolated.fingerprint,
        isolatedHeadOid: isolated.headOid,
        changedFiles: changedFiles.map((path) => toProjectPath(path, localPrefix)).sort(),
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async reviewIsolated(input: ReviewIsolatedInput): Promise<ReviewIsolatedResult> {
    if (!OID_PATTERN.test(input.baseOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidSessionBaseOIDFormat') } }
    }
    let tempRoot: string | null = null
    try {
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const prefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (prefix === null) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theLocalAndIsolatedProjectSubdirectoriesDoNotMatch') } }
      }
      await runGit(isolatedGitRoot, ['cat-file', '-e', `${input.baseOid}^{commit}`])
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-isolated-review-'))
      const excludes = deliveryExcludePathspecs(input.excludePaths)
      const isolated = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        null,
        null,
        excludes,
      )
      const changedTree = await changedTreePaths(isolatedGitRoot, input.baseOid, isolated.treeOid, null, null)
      if (changedTree.some((path) => !isProjectPath(path, prefix))) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootAReview') } }
      }
      return {
        status: 'ready',
        isolatedFingerprint: isolated.fingerprint,
        isolatedHeadOid: isolated.headOid,
        changedFiles: changedTree.map((path) => toProjectPath(path, prefix)).sort(),
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async commitIsolated(input: CommitIsolatedInput): Promise<CommitIsolatedResult> {
    const branch = input.branchRef ?? null
    if (!OID_PATTERN.test(input.baseOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidSessionBaseOIDFormat') } }
    }
    const commitMessage = input.commitMessage.trim()
    if (!commitMessage) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('worktreeFinishCommitMessageRequired') } }
    }
    let tempRoot: string | null = null
    let committedOid: string | undefined
    try {
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const prefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (prefix === null) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theLocalAndIsolatedProjectSubdirectoriesDoNotMatch') } }
      }
      await runGit(isolatedGitRoot, ['cat-file', '-e', `${input.baseOid}^{commit}`])
      const excludes = deliveryExcludePathspecs(input.excludePaths)
      const headOid = stdoutText(await runGit(isolatedGitRoot, ['rev-parse', 'HEAD']))
      const headTreeOid = stdoutText(await runGit(isolatedGitRoot, ['rev-parse', `${headOid}^{tree}`]))
      const symbolic = await runGit(isolatedGitRoot, ['symbolic-ref', '--quiet', 'HEAD'], { allowedExitCodes: [0, 1] })
      const headRef = symbolic.exitCode === 0 ? stdoutText(symbolic) : null
      if (branch && headRef !== branch) {
        // 调用方保证先挂好会话分支；这里只做守门，避免把提交落到 detached HEAD 上丢线。
        return {
          status: 'error',
          error: {
            code: 'operation_not_allowed',
            message: hostMessage('theWorktreeIsNotOnTheSessionBranch', { p0: branch, p1: headRef ?? 'HEAD' }),
          },
        }
      }

      // 提交树取自「评审快照」同一条构造路径（临时 index）：它已经排除了宿主
      // 运行期产物与随会话携带的 Project Skills，交付提交因此不会把这些东西带进
      // 会话分支；直接用真实 index 做 `add -A` 会把它们一起提交。
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-commit-snapshot-'))
      const pending = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'pending.index'),
        null,
        null,
        excludes,
      )
      const created = pending.treeOid !== headTreeOid
      // 变更集范围在动 ref 之前就校验：提交一旦写进分支就不可撤回，
      // 任何能提前判死的检查都不该排在它后面。
      const pendingTree = await changedTreePaths(isolatedGitRoot, input.baseOid, pending.treeOid, null, null)
      if (pendingTree.some((path) => !isProjectPath(path, prefix))) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootAReview') } }
      }
      let commitOid = headOid
      if (created) {
        commitOid = await createUserCommit(isolatedGitRoot, pending.treeOid, headOid, commitMessage)
        // HEAD 通常是符号引用，默认 deref 会把分支一起推到新提交。
        await runGit(isolatedGitRoot, ['update-ref', 'HEAD', commitOid, headOid])
        // 从这里往下分支 ref 已经前进；再失败也不能让调用方当成交付没发生。
        committedOid = commitOid
        // index 归位到新 HEAD；工作区文件不动。
        await runGit(isolatedGitRoot, ['reset', '--quiet'])
      }

      // 提交后的干净快照：既作为清理阶段的 CAS 指纹，也用于报告变更集。
      const snapshot = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        null,
        null,
        excludes,
      )
      if (snapshot.headOid !== commitOid) {
        return {
          status: 'error',
          error: { code: 'git_error', message: hostMessage('theWorktreeHeadDidNotAdvanceToTheDeliveryCommit') },
          ...(committedOid === undefined ? {} : { committedOid }),
        }
      }
      const changedTree = await changedTreePaths(isolatedGitRoot, input.baseOid, snapshot.treeOid, null, null)
      if (changedTree.some((path) => !isProjectPath(path, prefix))) {
        return {
          status: 'error',
          error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootAReview') },
          ...(committedOid === undefined ? {} : { committedOid }),
        }
      }
      return {
        status: 'committed',
        commitOid,
        changedFiles: changedTree.map((path) => toProjectPath(path, prefix)).sort(),
        isolatedFingerprint: snapshot.fingerprint,
        branch: headRef,
        created,
      }
    } catch (error) {
      const message = this.errorMessage(error)
      const residue = committedOid === undefined ? {} : { committedOid }
      // git 没配好提交身份时给一句可执行的提示，而不是让模型盯着 "empty ident" 猜。
      if (/empty ident|who you are|please tell me who/i.test(message)) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('initialIdentityMissing') }, ...residue }
      }
      return { status: 'error', error: { code: 'git_error', message }, ...residue }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async preflight(input: ApplyPlanInput): Promise<ApplyPlanResult> {
    return this.calculatePlan(input, false)
  }

async plan(input: ApplyPlanInput): Promise<ApplyPlanResult> {
    return this.calculatePlan(input, true)
  }

private async calculatePlan(input: ApplyPlanInput, persistPlan: boolean): Promise<ApplyPlanResult> {
    if (!OID_PATTERN.test(input.baseOid)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidSessionBaseOIDFormat') } }
    }

    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-apply-plan-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const localGitRoot = await resolveGitRoot(input.localPath)
      const isolatedGitRoot = await resolveGitRoot(input.isolatedPath)
      const localObjects = await sourceObjectDirectory(localGitRoot)
      const isolatedObjects = await sourceObjectDirectory(isolatedGitRoot)
      if (!pathsMatch(localObjects, isolatedObjects)) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('localAndIsolatedDoNotBelongToTheSame') } }
      }
      const localPrefix = projectPrefix(localGitRoot, input.localPath)
      const isolatedPrefix = projectPrefix(isolatedGitRoot, input.isolatedPath)
      if (localPrefix === null || isolatedPrefix === null || localPrefix !== isolatedPrefix) {
        return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theLocalAndIsolatedProjectSubdirectoriesDoNotMatch') } }
      }
      await runGit(localGitRoot, ['cat-file', '-e', `${input.baseOid}^{commit}`])

      const local = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'local.index'),
        objectDirectory,
        localObjects,
      )
      const isolated = await this.captureSnapshot(
        isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        localObjects,
      )
      const effectiveBase = await selectEffectiveApplyBase(
        localGitRoot,
        input.baseOid,
        local.headOid,
        isolated.headOid,
      )
      const isolatedChangedPaths = await changedTreePaths(
        isolatedGitRoot,
        effectiveBase.oid,
        isolated.treeOid,
        objectDirectory,
        localObjects,
      )
      if (isolatedChangedPaths.some((path) => !isProjectPath(path, localPrefix))) {
        return {
          status: 'error',
          error: { code: 'invalid_input', message: hostMessage('isolatedContainsChangesOutsideTheProjectRootApplyWas') },
        }
      }
      const merge = await computeMerge(
        tempRoot,
        localObjects,
        objectDirectory,
        effectiveBase.oid,
        local,
        isolated,
        localGitRoot,
        localPrefix,
      )
      const revision = randomUUID()
      if (merge.status === 'conflict') {
        return {
          status: 'conflict',
          revision,
          localFingerprint: local.fingerprint,
          isolatedFingerprint: isolated.fingerprint,
          effectiveBaseOid: effectiveBase.oid,
          baseStrategy: effectiveBase.strategy,
          localHeadOid: local.headOid,
          isolatedHeadOid: isolated.headOid,
          conflictingFiles: merge.conflictingFiles,
          ...(merge.conflictDetails ? { conflictDetails: merge.conflictDetails } : {}),
        }
      }

      const plan: ApplyPlan = {
        revision,
        localFingerprint: local.fingerprint,
        isolatedFingerprint: isolated.fingerprint,
        effectiveBaseOid: effectiveBase.oid,
        baseStrategy: effectiveBase.strategy,
        localHeadOid: local.headOid,
        localHeadRef: local.headRef,
        isolatedHeadOid: isolated.headOid,
        changedFiles: merge.changedFiles,
      }
      if (persistPlan) {
        // ponytail: this map must hold at most one stored plan per isolated
        // checkout — a freshly calculated plan supersedes the previous one for
        // the same path, so it cannot grow across repeated calculatePlan calls.
        for (const [storedRevision, storedPlan] of this.plans) {
          if (storedPlan.input.isolatedPath === input.isolatedPath) this.plans.delete(storedRevision)
        }
        this.plans.set(revision, {
          input: { ...input },
          patch: merge.patch,
          plan: { ...plan, changedFiles: [...plan.changedFiles] },
          scope: {
            isolatedGitRoot,
            localGitRoot,
            projectPrefix: localPrefix,
            sourceObjects: localObjects,
          },
        })
      }
      return { status: 'ready', plan: { ...plan, changedFiles: [...plan.changedFiles] } }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async apply(plan: ApplyPlan): Promise<ApplyResult> {
    const stored = this.plans.get(plan.revision)
    if (!stored || !planMatches(stored.plan, plan)) {
      return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theApplyPlanIsMissingAlreadyUsedOrModified') } }
    }

    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-apply-check-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(stored.scope.localGitRoot)
      if (!pathsMatch(sourceObjects, stored.scope.sourceObjects)) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theApplyPlanSGitRepositoryIdentityHasChanged') } }
      }
      const local = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (local.headOid !== stored.plan.localHeadOid || local.fingerprint !== stored.plan.localFingerprint) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedAfterPlanningRecalculateThePlan') } }
      }

      const isolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        sourceObjects,
      )
      if (isolated.headOid !== stored.plan.isolatedHeadOid || isolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }

      // 将已审核的 Isolated 最终状态写成无 ref 的内部 commit，供同一 checkout 后续 Apply 去重。
      // 使用独立 index，不改变 Isolated 的真实 staged/working tree。
      const persistentIsolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'persistent-isolated.index'),
        null,
        null,
      )
      if (persistentIsolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }
      const nextBaseOid = await createSnapshotCommit(
        stored.scope.isolatedGitRoot,
        persistentIsolated.treeOid,
        stored.plan.effectiveBaseOid,
        null,
        null,
        'Applied Isolated snapshot',
      )

      await this.options.beforeFinalLocalValidation?.()
      const finalLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'final-local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (finalLocal.headOid !== stored.plan.localHeadOid || finalLocal.fingerprint !== stored.plan.localFingerprint) {
        return {
          status: 'error',
          error: { code: 'stale_local', message: hostMessage('localChangedBeforeApplyWroteItsChangesRecalculateThe') },
        }
      }

      if (stored.patch.length > 0) {
        await runGit(stored.scope.localGitRoot, ['apply', '--binary', '--whitespace=nowarn'], { input: stored.patch })
      }
      this.plans.delete(plan.revision)
      return { status: 'applied', changedFiles: [...stored.plan.changedFiles], nextBaseOid }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async preview(
    plan: ApplyPlan,
    options: {
      previewId: string
      reviewId: string
      iteration: number
      beforeWrite?(receipt: PreviewReceipt): Promise<void>
    },
  ): Promise<PreviewResult> {
    const stored = this.plans.get(plan.revision)
    if (!stored || !planMatches(stored.plan, plan)) {
      return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('thePreviewPlanIsMissingAlreadyUsedOrModified') } }
    }
    if (!options.previewId.trim() || !options.reviewId.trim() || !Number.isSafeInteger(options.iteration) || options.iteration < 1) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('invalidPreviewIdentity') } }
    }

    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-preview-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(stored.scope.localGitRoot)
      if (!pathsMatch(sourceObjects, stored.scope.sourceObjects)) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('thePreviewPlanSGitRepositoryIdentityHasChanged') } }
      }
      const local = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        local.headOid !== stored.plan.localHeadOid
        || local.headRef !== stored.plan.localHeadRef
        || local.fingerprint !== stored.plan.localFingerprint
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedAfterPlanningRecalculateThePlan') } }
      }
      const isolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        sourceObjects,
      )
      if (isolated.headOid !== stored.plan.isolatedHeadOid || isolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }

      const persistentLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'persistent-local.index'),
        null,
        null,
      )
      const persistentIsolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'persistent-isolated.index'),
        null,
        null,
      )
      if (
        persistentLocal.fingerprint !== stored.plan.localFingerprint
        || persistentIsolated.fingerprint !== stored.plan.isolatedFingerprint
      ) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('thePersistentPreviewSnapshotDoesNotMatchTheReviewed') } }
      }
      const previewWorkingTreeOid = await prepareIndexFromPatch(
        stored.scope.localGitRoot,
        join(tempRoot, 'preview-working.index'),
        persistentLocal.treeOid,
        stored.patch,
      )
      const isolatedSnapshotOid = await createSnapshotCommit(
        stored.scope.isolatedGitRoot,
        persistentIsolated.treeOid,
        stored.plan.effectiveBaseOid,
        null,
        null,
        'Previewed Isolated snapshot',
      )
      const preparedReceipt: PreviewReceipt = {
        previewId: options.previewId,
        reviewId: options.reviewId,
        iteration: options.iteration,
        previewedAt: Date.now(),
        configuredBaseOid: stored.input.baseOid,
        effectiveBaseOid: stored.plan.effectiveBaseOid,
        baseStrategy: stored.plan.baseStrategy,
        localHeadOid: persistentLocal.headOid,
        localHeadRef: persistentLocal.headRef,
        localFingerprintBefore: persistentLocal.fingerprint,
        localFingerprintPreview: '',
        localWorkingTreeOid: persistentLocal.treeOid,
        localIndexTreeOid: persistentLocal.indexTreeOid,
        previewWorkingTreeOid,
        isolatedHeadOid: persistentIsolated.headOid,
        isolatedFingerprint: persistentIsolated.fingerprint,
        isolatedSnapshotOid,
        changedFiles: [...stored.plan.changedFiles],
      }

      await this.options.beforeFinalLocalValidation?.()
      const finalLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'final-local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (finalLocal.headOid !== stored.plan.localHeadOid || finalLocal.fingerprint !== stored.plan.localFingerprint) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforePreviewWroteItsChangesRecalculateThe') } }
      }
      await options.beforeWrite?.(preparedReceipt)
      if (stored.patch.length > 0) {
        await runGit(stored.scope.localGitRoot, ['apply', '--binary', '--whitespace=nowarn'], { input: stored.patch })
      }
      const previewedLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'previewed-local.index'),
        null,
        null,
      )
      if (previewedLocal.treeOid !== previewWorkingTreeOid) {
        return {
          status: 'error',
          error: { code: 'git_error', message: hostMessage('theLocalSnapshotAfterPreviewDoesNotMatchThe') },
        }
      }

      this.plans.delete(plan.revision)
      const receipt: PreviewReceipt = {
        ...preparedReceipt,
        localFingerprintPreview: previewedLocal.fingerprint,
      }
      return { status: 'previewed', receipt, changedFiles: [...receipt.changedFiles] }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async assessPreviewRecovery(input: { localPath: string; receipt: PreviewReceipt }): Promise<PreviewRecoveryAssessment | ApplyErrorResult> {
    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-preview-recovery-preflight-'))
      const localGitRoot = await resolveGitRoot(input.localPath)
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(localGitRoot)
      const current = await this.captureSnapshot(localGitRoot, join(tempRoot, 'current.index'), objectDirectory, sourceObjects)
      const rollback = await prepareRollbackAssessment(tempRoot, sourceObjects, objectDirectory, localGitRoot, current, input.receipt)
      const finalize = await prepareFinalizeAssessment(tempRoot, sourceObjects, objectDirectory, localGitRoot, current, input.receipt)
      return {
        localFingerprint: current.fingerprint,
        localHeadOid: current.headOid,
        localHeadRef: current.headRef,
        localHeadTreeOid: current.headTreeOid,
        localIndexTreeOid: current.indexTreeOid,
        localWorkingTreeOid: current.treeOid,
        rollback,
        finalize,
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async rollback(input: {
    localPath: string
    receipt: PreviewReceipt
    beforeWrite?(): Promise<void>
  }): Promise<RollbackResult> {
    let tempRoot: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-preview-rollback-'))
      const localGitRoot = await resolveGitRoot(input.localPath)
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(localGitRoot)
      const current = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'current.index'),
        objectDirectory,
        sourceObjects,
      )
      const assessment = await prepareRollbackAssessment(
        tempRoot,
        sourceObjects,
        objectDirectory,
        localGitRoot,
        current,
        input.receipt,
      )
      if (assessment.status === 'blocked') {
        return { status: 'error', error: { code: assessment.code, message: assessment.message } }
      }
      const rollbackPatch = await treePatch(
        localGitRoot,
        current.treeOid,
        assessment.targetTreeOid,
        objectDirectory,
        sourceObjects,
      )
      // Journal persistence may await registry I/O, so it must happen before the authoritative
      // final Local CAS. From the snapshot below to git apply there is no callback/yield seam.
      await input.beforeWrite?.()
      await this.options.beforeFinalLocalValidation?.()
      const finalLocal = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'final-local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        finalLocal.fingerprint !== current.fingerprint
        || finalLocal.headOid !== current.headOid
        || finalLocal.headRef !== current.headRef
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforePreviewRollbackRetry') } }
      }
      if (rollbackPatch.length > 0) {
        await runGit(localGitRoot, ['apply', '--binary', '--whitespace=nowarn'], { input: rollbackPatch })
      }
      let rolledBack: CheckoutSnapshot
      try {
        await this.options.afterLocalWriteBeforeVerification?.()
        rolledBack = await this.captureSnapshot(
          localGitRoot,
          join(tempRoot, 'rolled-back.index'),
          null,
          null,
        )
      } catch (error) {
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('cannotVerifyAfterWritingPreviewRollbackTheEnvironmentMust', { p0: this.errorMessage(error) }),
            recoveryState: 'uncertain',
          },
        }
      }
      const expectedFingerprint = snapshotFingerprint(
        current.headOid,
        current.headRef,
        current.indexEntries,
        assessment.targetTreeOid,
      )
      if (
        rolledBack.headOid !== current.headOid
        || rolledBack.headRef !== current.headRef
        || rolledBack.indexTreeOid !== current.indexTreeOid
        || rolledBack.treeOid !== assessment.targetTreeOid
        || rolledBack.fingerprint !== expectedFingerprint
      ) {
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('theLocalSnapshotAfterPreviewRollbackDoesNotMatch'),
            recoveryState: 'uncertain',
          },
        }
      }
      return { status: 'preview_rolled_back', changedFiles: [...input.receipt.changedFiles] }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async finalize(input: {
    localPath: string
    receipt: PreviewReceipt
    commitMessage: string
    beforeCommit?(commitOid: string): Promise<void>
  }): Promise<FinishResult> {
    const commitMessage = input.commitMessage.trim()
    if (!isValidCommitMessage(commitMessage)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theCommitMessageMustBeNonemptyAndContainNoNul') } }
    }

    let tempRoot: string | null = null
    let ownedIndexLock: string | null = null
    let backupIndex: string | null = null
    let preserveBackup = false
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-preview-finalize-'))
      const localGitRoot = await resolveGitRoot(input.localPath)
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(localGitRoot)
      const current = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'current.index'),
        objectDirectory,
        sourceObjects,
      )
      const realIndexPath = await resolveIndexPath(localGitRoot)
      const originalIndexBytes = await readFile(realIndexPath)
      const assessment = await prepareFinalizeAssessment(
        tempRoot,
        sourceObjects,
        objectDirectory,
        localGitRoot,
        current,
        input.receipt,
      )
      if (assessment.status === 'blocked') {
        return { status: 'error', error: { code: assessment.code, message: assessment.message } }
      }

      if (!assessment.commitRequired) {
        await this.options.beforeFinalLocalValidation?.()
        const finalLocal = await this.captureSnapshot(
          localGitRoot,
          join(tempRoot, 'final-empty.index'),
          objectDirectory,
          sourceObjects,
        )
        if (
          finalLocal.headOid !== current.headOid
          || finalLocal.headRef !== current.headRef
          || finalLocal.fingerprint !== current.fingerprint
        ) {
          return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeFinalizingPreviewRetry') } }
        }
        return {
          status: 'finished',
          changedFiles: [],
          commitOid: null,
          nextBaseOid: input.receipt.isolatedSnapshotOid,
        }
      }

      const taskPatch = await treePatch(
        localGitRoot,
        current.headTreeOid,
        assessment.taskTreeOid,
        objectDirectory,
        sourceObjects,
      )
      const finalIndexPatch = await treePatch(
        localGitRoot,
        assessment.taskTreeOid,
        assessment.finalIndexTreeOid,
        objectDirectory,
        sourceObjects,
      )
      const actualTaskTreeOid = await prepareIndexFromPatch(
        localGitRoot,
        join(tempRoot, 'task.index'),
        current.headOid,
        taskPatch,
      )
      if (actualTaskTreeOid !== assessment.taskTreeOid) {
        return { status: 'error', error: { code: 'git_error', message: hostMessage('thePreviewTaskCommitTreeDoesNotMatchThe') } }
      }
      const commitOid = await createUserCommit(localGitRoot, actualTaskTreeOid, current.headOid, commitMessage)
      const finalIndexPath = join(tempRoot, 'final.index')
      const actualFinalIndexTreeOid = await prepareIndexFromPatch(
        localGitRoot,
        finalIndexPath,
        commitOid,
        finalIndexPatch,
      )
      if (actualFinalIndexTreeOid !== assessment.finalIndexTreeOid) {
        return { status: 'error', error: { code: 'git_error', message: hostMessage('thePreviewFinalIndexTreeDoesNotMatchThe') } }
      }
      const expectedIndexEntries = (
        await runGit(localGitRoot, ['ls-files', '--stage', '-z'], { env: { GIT_INDEX_FILE: finalIndexPath } })
      ).stdout
      const intendedIndexBytes = await readFile(finalIndexPath)
      const expectedFingerprint = snapshotFingerprint(
        commitOid,
        current.headRef,
        expectedIndexEntries,
        assessment.expectedWorkingTreeOid,
      )
      await input.beforeCommit?.(commitOid)

      const branchRef = current.headRef
      if (!branchRef?.startsWith('refs/heads/')) {
        return { status: 'error', error: { code: 'operation_not_allowed', message: hostMessage('localIsNotOnANormalBranchATask') } }
      }
      backupIndex = `${realIndexPath}.domi-backup-${randomUUID()}`
      await copyFile(realIndexPath, backupIndex)
      await this.options.beforeFinalLocalValidation?.()
      try {
        // Use Git's canonical index.lock protocol. While this lock exists, concurrent git add/reset
        // cannot mutate the real index between the authoritative snapshot and our atomic replacement.
        ownedIndexLock = await writeIndexLock(realIndexPath, intendedIndexBytes)
      } catch (error) {
        if (isIndexLockContention(error)) {
          return { status: 'error', error: { code: 'stale_local', message: hostMessage('anotherGitOperationIsUpdatingTheLocalIndexRetry') } }
        }
        throw error
      }
      const finalLocal = await this.captureSnapshot(
        localGitRoot,
        join(tempRoot, 'final-local.index'),
        objectDirectory,
        sourceObjects,
      )
      const finalIndexBytes = await readFile(realIndexPath)
      if (
        finalLocal.headOid !== current.headOid
        || finalLocal.headRef !== current.headRef
        || finalLocal.fingerprint !== current.fingerprint
        || !finalIndexBytes.equals(originalIndexBytes)
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeThePreviewCommitWasWrittenRetry') } }
      }

      let refUpdated = false
      let indexReplaced = false
      let writeError: unknown = null
      try {
        await runGit(localGitRoot, ['update-ref', branchRef, commitOid, current.headOid])
        refUpdated = true
        await rename(ownedIndexLock, realIndexPath)
        ownedIndexLock = null
        indexReplaced = true
      } catch (error) {
        writeError = error
      }

      if (!writeError) {
        try {
          await this.options.afterLocalWriteBeforeVerification?.()
          const committed = await this.captureSnapshot(
            localGitRoot,
            join(tempRoot, 'committed.index'),
            null,
            null,
          )
          const committedIndexBytes = await readFile(realIndexPath)
          if (
            committed.headOid === commitOid
            && committed.headRef === branchRef
            && committed.indexTreeOid === assessment.finalIndexTreeOid
            && committed.treeOid === assessment.expectedWorkingTreeOid
            && committed.fingerprint === expectedFingerprint
            && committedIndexBytes.equals(intendedIndexBytes)
          ) {
            await removeBestEffort(backupIndex)
            backupIndex = null
            return {
              status: 'finished',
              changedFiles: [...input.receipt.changedFiles],
              commitOid,
              nextBaseOid: input.receipt.isolatedSnapshotOid,
            }
          }
          writeError = new Error(hostMessage('previewCommitVerificationFailedAfterWriting'))
        } catch (error) {
          writeError = error
        }
      }

      const rollbackErrors: string[] = []
      if (refUpdated && !indexReplaced && ownedIndexLock) {
        // The ref moved but the index replacement did not. We still own index.lock, so no Git
        // index writer can race the ref CAS rollback; the real index is already the original one.
        try {
          await runGit(localGitRoot, ['update-ref', branchRef, current.headOid, commitOid])
          refUpdated = false
          await removeBestEffort(ownedIndexLock)
          ownedIndexLock = null
        } catch (error) {
          rollbackErrors.push(`ref: ${this.errorMessage(error)}`)
        }
      } else if (refUpdated && indexReplaced && backupIndex) {
        // Compensation is itself a CAS transaction. Never restore the old backup over an index
        // that changed after Domi's write; preserve both the user's index and our backup instead.
        try {
          const backupBytes = await readFile(backupIndex)
          ownedIndexLock = await writeIndexLock(realIndexPath, backupBytes)
          const currentIndexBytes = await readFile(realIndexPath)
          if (!currentIndexBytes.equals(intendedIndexBytes)) {
            rollbackErrors.push(hostMessage('indexLocalIndexChangedAfterPreviewWroteItsChanges'))
          } else {
            await runGit(localGitRoot, ['update-ref', branchRef, current.headOid, commitOid])
            refUpdated = false
            await rename(ownedIndexLock, realIndexPath)
            ownedIndexLock = null
            indexReplaced = false
          }
        } catch (error) {
          rollbackErrors.push(`compensation: ${this.errorMessage(error)}`)
        }
      } else if (refUpdated) {
        rollbackErrors.push(hostMessage('refVerifiableIndexCompensationEvidenceIsMissingPartialRollback'))
      }

      let restored = false
      if (rollbackErrors.length === 0) {
        try {
          const restoredLocal = await this.captureSnapshot(
            localGitRoot,
            join(tempRoot, 'restored.index'),
            null,
            null,
          )
          const restoredIndexBytes = await readFile(realIndexPath)
          restored = restoredLocal.headOid === current.headOid
            && restoredLocal.headRef === current.headRef
            && restoredLocal.indexTreeOid === current.indexTreeOid
            && restoredLocal.treeOid === current.treeOid
            && restoredLocal.fingerprint === current.fingerprint
            && restoredIndexBytes.equals(originalIndexBytes)
        } catch (error) {
          rollbackErrors.push(`verification: ${this.errorMessage(error)}`)
        }
      }
      if (restored) {
        await removeBestEffort(backupIndex)
        backupIndex = null
        return {
          status: 'error',
          error: {
            code: 'git_error',
            message: hostMessage('thePreviewCommitWriteCouldNotBeVerifiedAnd', { p0: this.errorMessage(writeError) }),
            recoveryState: 'unchanged',
          },
        }
      }

      preserveBackup = true
      const rollbackDetail = rollbackErrors.length > 0 ? `；${rollbackErrors.join('；')}` : ''
      return {
        status: 'error',
        error: {
          code: 'git_error',
          message: hostMessage('cannotProveSuccessOrCompleteRollbackAfterWritingThe', { p0: this.errorMessage(writeError), p1: rollbackDetail, p2: backupIndex ?? 'unknown' }),
          recoveryState: 'uncertain',
        },
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      await removeBestEffort(ownedIndexLock)
      if (!preserveBackup) await removeBestEffort(backupIndex)
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

async finish(plan: ApplyPlan, options: { commitMessage: string }): Promise<FinishResult> {
    const stored = this.plans.get(plan.revision)
    if (!stored || !planMatches(stored.plan, plan)) {
      return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theFinishPlanIsMissingAlreadyUsedOrModified') } }
    }
    const commitMessage = options.commitMessage.trim()
    if (!isValidCommitMessage(commitMessage)) {
      return { status: 'error', error: { code: 'invalid_input', message: hostMessage('theCommitMessageMustBeNonemptyAndContainNoNul') } }
    }
    if (!stored.plan.localHeadRef?.startsWith('refs/heads/')) {
      return {
        status: 'error',
        error: { code: 'operation_not_allowed', message: hostMessage('localIsNotOnANormalBranchATask') },
      }
    }

    let tempRoot: string | null = null
    let ownedIndexLock: string | null = null
    try {
      tempRoot = await mkdtemp(join(tmpdir(), 'domi-finish-'))
      const objectDirectory = join(tempRoot, 'objects')
      await mkdir(objectDirectory, { recursive: true })
      const sourceObjects = await sourceObjectDirectory(stored.scope.localGitRoot)
      if (!pathsMatch(sourceObjects, stored.scope.sourceObjects)) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theFinishPlanSGitRepositoryIdentityHasChanged') } }
      }

      const local = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'local.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        local.headOid !== stored.plan.localHeadOid
        || local.headRef !== stored.plan.localHeadRef
        || local.fingerprint !== stored.plan.localFingerprint
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedAfterPlanningRecalculateThePlan') } }
      }
      const isolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'isolated.index'),
        objectDirectory,
        sourceObjects,
      )
      if (isolated.headOid !== stored.plan.isolatedHeadOid || isolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }

      const merge = await computeMerge(
        tempRoot,
        sourceObjects,
        objectDirectory,
        stored.plan.effectiveBaseOid,
        local,
        isolated,
        stored.scope.localGitRoot,
        stored.scope.projectPrefix,
      )
      if (merge.status === 'conflict') {
        return {
          status: 'error',
          error: { code: 'invalid_plan', message: hostMessage('finishRevalidationFoundConflictsInconsistentWithTheReviewedPlan') },
        }
      }
      if (
        merge.changedFiles.length !== stored.plan.changedFiles.length
        || merge.changedFiles.some((path, index) => path !== stored.plan.changedFiles[index])
      ) {
        return { status: 'error', error: { code: 'invalid_plan', message: hostMessage('theFileSetChangedDuringFinishRevalidation') } }
      }

      const persistentIsolated = await this.captureSnapshot(
        stored.scope.isolatedGitRoot,
        join(tempRoot, 'persistent-isolated.index'),
        null,
        null,
      )
      if (persistentIsolated.fingerprint !== stored.plan.isolatedFingerprint) {
        return { status: 'error', error: { code: 'stale_isolated', message: hostMessage('isolatedChangedAfterPlanningRecalculateThePlan') } }
      }
      const nextBaseOid = await createSnapshotCommit(
        stored.scope.isolatedGitRoot,
        persistentIsolated.treeOid,
        stored.plan.effectiveBaseOid,
        null,
        null,
        'Finished Isolated snapshot',
      )

      if (merge.changedFiles.length === 0) {
        await this.options.beforeFinalLocalValidation?.()
        const finalLocal = await this.captureSnapshot(
          stored.scope.localGitRoot,
          join(tempRoot, 'final-local.index'),
          objectDirectory,
          sourceObjects,
        )
        if (finalLocal.fingerprint !== stored.plan.localFingerprint) {
          return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeFinishRecalculateThePlan') } }
        }
        this.plans.delete(plan.revision)
        return { status: 'finished', changedFiles: [], commitOid: null, nextBaseOid }
      }

      // C = H + (M - L)：把任务增量从完整 Local 快照 L 中剥离，重放到旧 HEAD H。
      const taskTree = await computeTreeMerge(
        tempRoot,
        sourceObjects,
        objectDirectory,
        stored.scope.localGitRoot,
        'finish-task-isolation',
        local.treeOid,
        local.headTreeOid,
        merge.mergedTreeOid,
      )
      if (taskTree.status === 'conflict') {
        return {
          status: 'error',
          error: {
            code: 'commit_isolation_conflict',
            message: hostMessage('taskChangesCannotBeReliablySeparatedFromExistingLocal', { p0: taskTree.conflictingFiles.join('、') }),
          },
        }
      }

      // S' = C + (S - H)：在任务提交 C 上恢复用户原有 staged 状态。
      const finalIndexTree = await computeTreeMerge(
        tempRoot,
        sourceObjects,
        objectDirectory,
        stored.scope.localGitRoot,
        'finish-index-preservation',
        local.headTreeOid,
        taskTree.treeOid,
        local.indexTreeOid,
      )
      if (finalIndexTree.status === 'conflict') {
        return {
          status: 'error',
          error: {
            code: 'commit_isolation_conflict',
            message: hostMessage('theTaskCommitCannotBeReliablySeparatedFromExisting', { p0: finalIndexTree.conflictingFiles.join('、') }),
          },
        }
      }

      const taskPatch = await treePatch(
        stored.scope.localGitRoot,
        local.headTreeOid,
        taskTree.treeOid,
        objectDirectory,
        sourceObjects,
      )
      const finalIndexPatch = await treePatch(
        stored.scope.localGitRoot,
        taskTree.treeOid,
        finalIndexTree.treeOid,
        objectDirectory,
        sourceObjects,
      )
      const taskIndexPath = join(tempRoot, 'task-commit.index')
      const actualTaskTreeOid = await prepareIndexFromPatch(
        stored.scope.localGitRoot,
        taskIndexPath,
        local.headOid,
        taskPatch,
      )
      const commitOid = await createUserCommit(
        stored.scope.localGitRoot,
        actualTaskTreeOid,
        local.headOid,
        commitMessage,
      )
      const finalIndexPath = join(tempRoot, 'preserved-local.index')
      await prepareIndexFromPatch(
        stored.scope.localGitRoot,
        finalIndexPath,
        commitOid,
        finalIndexPatch,
      )

      await this.options.beforeFinalLocalValidation?.()
      const finalLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'final-local-validation.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        finalLocal.headOid !== stored.plan.localHeadOid
        || finalLocal.headRef !== stored.plan.localHeadRef
        || finalLocal.fingerprint !== stored.plan.localFingerprint
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeFinishWroteItsChangesRecalculateThe') } }
      }

      const realIndexPath = await resolveIndexPath(stored.scope.localGitRoot)
      // Git 的 index.lock 协议：持锁期间并发 git add/reset 无法改写真实 index，
      // 校验→打补丁→update-ref→换 index 在同一把锁内完成（与 finalize 对齐）。
      try {
        ownedIndexLock = await writeIndexLock(realIndexPath, await readFile(finalIndexPath))
      } catch (error) {
        if (isIndexLockContention(error)) {
          return { status: 'error', error: { code: 'stale_local', message: hostMessage('anotherGitOperationIsUpdatingTheLocalIndexRetry') } }
        }
        throw error
      }
      const lockedLocal = await this.captureSnapshot(
        stored.scope.localGitRoot,
        join(tempRoot, 'locked-local-validation.index'),
        objectDirectory,
        sourceObjects,
      )
      if (
        lockedLocal.headOid !== stored.plan.localHeadOid
        || lockedLocal.headRef !== stored.plan.localHeadRef
        || lockedLocal.fingerprint !== stored.plan.localFingerprint
      ) {
        return { status: 'error', error: { code: 'stale_local', message: hostMessage('localChangedBeforeFinishWroteItsChangesRecalculateThe') } }
      }

      let worktreePatched = false
      let refUpdated = false
      try {
        if (merge.patch.length > 0) {
          await runGit(stored.scope.localGitRoot, ['apply', '--binary', '--whitespace=nowarn'], { input: merge.patch })
          worktreePatched = true
        }
        await runGit(stored.scope.localGitRoot, [
          'update-ref',
          stored.plan.localHeadRef,
          commitOid,
          local.headOid,
        ])
        refUpdated = true
        await rename(ownedIndexLock, realIndexPath)
        ownedIndexLock = null
      } catch (error) {
        const rollbackErrors: string[] = []
        if (refUpdated) {
          try {
            await runGit(stored.scope.localGitRoot, [
              'update-ref',
              stored.plan.localHeadRef,
              local.headOid,
              commitOid,
            ])
          } catch (rollbackError) {
            rollbackErrors.push(`ref: ${this.errorMessage(rollbackError)}`)
          }
        }
        if (worktreePatched) {
          try {
            await runGit(stored.scope.localGitRoot, ['apply', '-R', '--binary', '--whitespace=nowarn'], { input: merge.patch })
          } catch (rollbackError) {
            rollbackErrors.push(`worktree: ${this.errorMessage(rollbackError)}`)
          }
        }
        const detail = this.errorMessage(error)
        if (rollbackErrors.length > 0) {
          return {
            status: 'error',
            error: {
              code: 'git_error',
              message: hostMessage('finishWriteFailedAndCompleteRollbackCouldNotBe', { p0: detail, p1: rollbackErrors.join('；') }),
            },
          }
        }
        return { status: 'error', error: { code: 'git_error', message: hostMessage('finishWriteFailedAndWasRolledBack', { p0: detail }) } }
      }

      this.plans.delete(plan.revision)
      return {
        status: 'finished',
        changedFiles: [...stored.plan.changedFiles],
        commitOid,
        nextBaseOid,
      }
    } catch (error) {
      return { status: 'error', error: { code: 'git_error', message: this.errorMessage(error) } }
    } finally {
      await removeBestEffort(ownedIndexLock)
      if (tempRoot) await this.cleanup(tempRoot)
    }
  }

private errorMessage(error: unknown): string {
    if (error instanceof GitCommandFailure) {
      return hostMessage('gitOperationFailed', { p0: error.args[0] ?? 'unknown', p1: error.message })
    }
    return error instanceof Error ? error.message : hostMessage('unknownGitError')
  }

private async cleanup(path: string): Promise<void> {
    try {
      await rm(path, { recursive: true, force: true, maxRetries: 2 })
    } catch (error) {
      // 清理失败不能掩盖 plan/apply 的主结果。
      console.warn(hostMessage('tempDirectoryCleanupFailed'), error)
    }
  }

