function sessionIdOf(agent: unknown): string {
  const session = (agent as { session?: { id: unknown } } | undefined)?.session
  if (!session || typeof session.id !== 'string') {
    throw new Error(hostMessage('worktreeToolsCanOnlyBeCalledInADSH'))
  }
  return session.id
}

